TEST_CASE("encode: offset table follows the dense/hashed split")
{
    HashGrid grid;
    HashGridConfig c;
    c.n_levels          = 6;
    c.features_per_level = 2;
    c.log2_hashmap_size = 10; // 1024 entries
    c.base_resolution   = 4;
