        for(auto &v : A)
        {
            v = rng.uniform(-1.f, 1.f);
        }
        for(auto &v : B)
        {
            v = rng.uniform(-1.f, 1.f);
        }
        for(auto &v : bias)
        {
            v = rng.uniform(-0.5f, 0.5f);
        }
        DeviceBuffer<float> dA, dB, db, dC(M * N);
        dA.upload(A);
        dB.upload(B);
