// The shorter image side spans an NDC range of 2; the longer side is scaled
// by the aspect ratio. S1 is the dimension the range is computed for.
TSR_HDI float non_square_ndc_range(int S1, int S2)
{
    float range = 2.0f;
    if(S1 > S2)
    {
        range = (S1 * range) / S2;
    }
    return range;
}

// NDC coordinate of the centre of raster index i along a dimension of size
// S1. Raster indices grow with NDC, i.e. towards +x (left) / +y (up).
TSR_HDI float pix_to_non_square_ndc(int i, int S1, int S2)
{
    const float range  = non_square_ndc_range(S1, S2);
    const float offset = range / 2.0f;
    return -offset + (range * i + offset) / S1;
}

// Continuous pixel coordinate (origin top-left, +x right) -> NDC x.
// Pixel centre u = c + 0.5 maps to pix_to_non_square_ndc(W - 1 - c, W, H).
TSR_HDI float pixel_x_to_ndc(float u, int W, int H)
{
    return non_square_ndc_range(W, H) * (0.5f - u / static_cast<float>(W));
}

// Continuous pixel coordinate (origin top-left, +y down) -> NDC y.
TSR_HDI float pixel_y_to_ndc(float v, int H, int W)
{
    return non_square_ndc_range(H, W) * (0.5f - v / static_cast<float>(H));
}

} // namespace tsr::geom

// Tessera - device-wide prefix sums.
//
// Hierarchical scan after the cuda-samples "scan" sample (BSD-3-Clause):
//   1. scan_tiles_kernel     scans 1024-element tiles (256 threads x 4 items)
//                            and records each tile's total
//   2. (recursion)           exclusive scan of the tile totals
//   3. uniform_add_kernel    adds each tile's offset to its elements
// Unlike the sample, lengths need not be powers of two: the tail tile is
// zero-padded on load and masked on store.
#include "tsr/prims/block.cuh"
#include "tsr/prims/prims.h"

namespace tsr::prims
{
namespace
{
constexpr unsigned kScanThreads = 256;
constexpr unsigned kScanItems   = 4;
constexpr unsigned kScanTile    = kScanThreads * kScanItems;

// `in` and `out` may alias (in-place scans), so they are not __restrict__.
template<typename T>
__global__ void __launch_bounds__(kScanThreads)
    scan_tiles_kernel(const T *in, T *out, T *__restrict__ tile_totals, std::uint64_t n, bool inclusive)
{
    cg::thread_block cta = cg::this_thread_block();
    __shared__ T s_data[2 * kScanThreads];

    const std::uint64_t base = static_cast<std::uint64_t>(blockIdx.x) * kScanTile + threadIdx.x * kScanItems;
    T items[kScanItems];
    T original[kScanItems];
    TSR_UNROLL
    for(unsigned k = 0; k < kScanItems; ++k)
    {
        items[k]    = base + k < n ? in[base + k] : T(0);
        original[k] = items[k];
    }

    T tile_total;
    scan4_exclusive(items, s_data, kScanThreads, cta, tile_total);

    TSR_UNROLL
    for(unsigned k = 0; k < kScanItems; ++k)
    {
        if(base + k < n)
        {
            out[base + k] = inclusive ? items[k] + original[k] : items[k];
        }
    }
    if(tile_totals != nullptr && threadIdx.x == 0)
    {
        tile_totals[blockIdx.x] = tile_total;
    }
}

template<typename T>
__global__ void __launch_bounds__(kScanThreads)
    uniform_add_kernel(T *__restrict__ data, const T *__restrict__ tile_offsets, std::uint64_t n)
{
    cg::thread_block cta = cg::this_thread_block();
    __shared__ T buf;
    if(threadIdx.x == 0)
    {
        buf = tile_offsets[blockIdx.x];
    }
    cg::sync(cta);

    const std::uint64_t base = static_cast<std::uint64_t>(blockIdx.x) * kScanTile + threadIdx.x * kScanItems;
    TSR_UNROLL
    for(unsigned k = 0; k < kScanItems; ++k)
    {
        if(base + k < n)
        {
            data[base + k] += buf;
        }
    }
}

template<typename T>
void scan_impl(const T *in, T *out, std::size_t n, bool inclusive, Arena &arena, cudaStream_t stream)
{
    if(n == 0)
    {
        return;
    }
    const std::uint64_t tiles = div_round_up<std::uint64_t>(n, kScanTile);
    TSR_CHECK(tiles <= 0x7fffffffu, "scan of " << n << " elements exceeds the grid limit");
    T *tile_totals = tiles > 1 ? arena.allocate<T>(tiles) : nullptr;

    launch(
        scan_tiles_kernel<T>,
        LaunchConfig{dim3(static_cast<unsigned>(tiles)), dim3(kScanThreads), 0, stream},
        in,
        out,
        tile_totals,
        static_cast<std::uint64_t>(n),
        inclusive
    );
    if(tiles > 1)
    {
        scan_impl(tile_totals, tile_totals, tiles, false, arena, stream);
        launch(
            uniform_add_kernel<T>,
            LaunchConfig{dim3(static_cast<unsigned>(tiles)), dim3(kScanThreads), 0, stream},
            out,
            tile_totals,
            static_cast<std::uint64_t>(n)
        );
    }
}
} // namespace

template<typename T>
void exclusive_scan(const T *in, T *out, std::size_t n, Arena &arena, cudaStream_t stream)
{
    scan_impl(in, out, n, false, arena, stream);
}

template<typename T>
void inclusive_scan(const T *in, T *out, std::size_t n, Arena &arena, cudaStream_t stream)
{
    scan_impl(in, out, n, true, arena, stream);
}

template<typename T>
T exclusive_scan_total(const T *in, T *out, std::size_t n, Arena &arena, cudaStream_t stream)
{
    if(n == 0)
    {
        return T(0);
    }
    // Read the last input before the scan: with in == out it is overwritten.
    T last_in = T(0);
    TSR_CUDA_CHECK(cudaMemcpyAsync(&last_in, in + n - 1, sizeof(T), cudaMemcpyDeviceToHost, stream));
    TSR_CUDA_CHECK(cudaStreamSynchronize(stream));
    scan_impl(in, out, n, false, arena, stream);
    T last_out = T(0);
    TSR_CUDA_CHECK(cudaMemcpyAsync(&last_out, out + n - 1, sizeof(T), cudaMemcpyDeviceToHost, stream));
    TSR_CUDA_CHECK(cudaStreamSynchronize(stream));
    return last_out + last_in;
}

#define TSR_INSTANTIATE_SCAN(T)                                                                    \
    template void exclusive_scan<T>(const T *, T *, std::size_t, Arena &, cudaStream_t);           \
    template void inclusive_scan<T>(const T *, T *, std::size_t, Arena &, cudaStream_t);           \
    template T exclusive_scan_total<T>(const T *, T *, std::size_t, Arena &, cudaStream_t);

TSR_INSTANTIATE_SCAN(std::uint32_t)
TSR_INSTANTIATE_SCAN(std::int32_t)
TSR_INSTANTIATE_SCAN(std::uint64_t)
TSR_INSTANTIATE_SCAN(std::int64_t)
TSR_INSTANTIATE_SCAN(float)

#undef TSR_INSTANTIATE_SCAN
} // namespace tsr::prims
// Tessera - device-wide reductions.
//
// Two-pass reduction modelled on reduce7 from the cuda-samples "reduction"
// sample (BSD-3-Clause): a grid-stride loop accumulates several elements per
// thread, warps reduce with shuffles and one warp folds the per-warp partials.
// The first pass writes one partial per block, the second pass runs a single
// block over the partials.
//
// Differences from the sample: the operation is a template parameter, and the
// final warp reduction runs over the full warp with identity padding instead
// of a ballot-derived partial mask (shuffling from lanes outside the mask is
// undefined behaviour that the sample relies on).
#include <algorithm>

#include "tsr/prims/block.cuh"
#include "tsr/prims/prims.h"

namespace tsr::prims
{
namespace
{
constexpr unsigned kReduceThreads = 256;
constexpr unsigned kMaxPartials   = 512;

template<typename T, typename Op, bool kTwoPerThread>
__global__ void __launch_bounds__(kReduceThreads)
    reduce_kernel(const T *__restrict__ in, T *__restrict__ out, std::uint64_t n)
{
    __shared__ T s_warp[kReduceThreads / kWarpSize];
    const Op op{};
    T acc = Op::identity();

    if constexpr(kTwoPerThread)
    {
        // Each iteration consumes two blocks' worth of elements.
        std::uint64_t i               = static_cast<std::uint64_t>(blockIdx.x) * kReduceThreads * 2 + threadIdx.x;
        const std::uint64_t grid_size = static_cast<std::uint64_t>(kReduceThreads) * 2 * gridDim.x;
        while(i < n)
        {
            acc = op(acc, in[i]);
            if(i + kReduceThreads < n)
            {
                acc = op(acc, in[i + kReduceThreads]);
            }
            i += grid_size;
        }
    }
    else
    {
        std::uint64_t i               = static_cast<std::uint64_t>(blockIdx.x) * kReduceThreads + threadIdx.x;
        const std::uint64_t grid_size = static_cast<std::uint64_t>(kReduceThreads) * gridDim.x;
        while(i < n)
        {
            acc = op(acc, in[i]);
            i  += grid_size;
        }
    }

    acc = block_reduce<kReduceThreads>(acc, op, s_warp);
    if(threadIdx.x == 0)
    {
        out[blockIdx.x] = acc;
    }
}

template<typename T, typename Op>
void reduce_with(const T *in, std::size_t n, T *out, Arena &arena, cudaStream_t stream)
{
    // Enough blocks to keep every worker busy, few enough that the second
    // pass is a single block.
    const unsigned blocks = static_cast<unsigned>(std::clamp<std::size_t>(div_round_up<std::size_t>(n, kReduceThreads * 8), 1, kMaxPartials));
    T *partials           = arena.allocate<T>(blocks);
    const bool pow2       = n > 0 && (n & (n - 1)) == 0;
    if(pow2)
    {
        launch(reduce_kernel<T, Op, true>, LaunchConfig{dim3(blocks), dim3(kReduceThreads), 0, stream}, in, partials, static_cast<std::uint64_t>(n));
    }
    else
    {
        launch(reduce_kernel<T, Op, false>, LaunchConfig{dim3(blocks), dim3(kReduceThreads), 0, stream}, in, partials, static_cast<std::uint64_t>(n));
    }
    launch(reduce_kernel<T, Op, false>, LaunchConfig{dim3(1), dim3(kReduceThreads), 0, stream}, partials, out, static_cast<std::uint64_t>(blocks));
}
} // namespace

template<typename T>
void reduce(const T *in, std::size_t n, T *out, ReduceOp op, Arena &arena, cudaStream_t stream)
{
    switch(op)
    {
    case ReduceOp::Sum: reduce_with<T, SumOp<T>>(in, n, out, arena, stream); break;
    case ReduceOp::Max: reduce_with<T, MaxOp<T>>(in, n, out, arena, stream); break;
    case ReduceOp::Min: reduce_with<T, MinOp<T>>(in, n, out, arena, stream); break;
    }
}

template void reduce<float>(const float *, std::size_t, float *, ReduceOp, Arena &, cudaStream_t);
template void reduce<std::uint32_t>(const std::uint32_t *, std::size_t, std::uint32_t *, ReduceOp, Arena &, cudaStream_t);
template void reduce<std::int32_t>(const std::int32_t *, std::size_t, std::int32_t *, ReduceOp, Arena &, cudaStream_t);
} // namespace tsr::prims
// Tessera - 256-bin histogram.
//
// After histogram256 from the cuda-samples "histogram" sample (BSD-3-Clause):
// every warp owns a private sub-histogram in shared memory to spread atomic
// contention, the sub-histograms are merged per block into partial
// histograms, and a second kernel (one block per bin) sums the partials.
// The input here is one bin index per element instead of four packed bytes.
#include <algorithm>

#include "tsr/prims/prims.h"
#include "tsr/prims/warp.cuh"

namespace tsr::prims
{
namespace
{
constexpr unsigned kHistWarps       = 6;
constexpr unsigned kHistThreads     = kHistWarps * kWarpSize;
constexpr unsigned kHistBlockMemory = kHistWarps * kHistogramBins;
constexpr unsigned kMaxPartials     = 240;
constexpr unsigned kMergeThreads    = 256;

__global__ void __launch_bounds__(kHistThreads)
    histogram256_kernel(std::uint32_t *__restrict__ partials, const std::uint32_t *__restrict__ bins, std::uint64_t n)
{
    cg::thread_block cta = cg::this_thread_block();
    __shared__ std::uint32_t s_hist[kHistBlockMemory];
    std::uint32_t *s_warp_hist = s_hist + warp_id() * kHistogramBins;

    TSR_UNROLL
    for(unsigned i = 0; i < kHistBlockMemory / kHistThreads; ++i)
    {
        s_hist[threadIdx.x + i * kHistThreads] = 0;
    }
    cg::sync(cta);

    const std::uint64_t stride = static_cast<std::uint64_t>(blockDim.x) * gridDim.x;
    for(std::uint64_t pos = static_cast<std::uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x; pos < n; pos += stride)
    {
        const std::uint32_t b = bins[pos];
        if(b < kHistogramBins)
        {
            atomicAdd(s_warp_hist + b, 1u);
        }
    }
    cg::sync(cta);

    for(unsigned bin = threadIdx.x; bin < kHistogramBins; bin += kHistThreads)
    {
        std::uint32_t sum = 0;
        for(unsigned w = 0; w < kHistWarps; ++w)
        {
            sum += s_hist[bin + w * kHistogramBins];
        }
        partials[blockIdx.x * kHistogramBins + bin] = sum;
    }
}

// One block per bin: each block adds up the same bin from every partial.
__global__ void __launch_bounds__(kMergeThreads)
    merge_histogram256_kernel(std::uint32_t *__restrict__ hist, const std::uint32_t *__restrict__ partials, unsigned partial_count)
{
    cg::thread_block cta = cg::this_thread_block();
    std::uint32_t sum    = 0;
    for(unsigned i = threadIdx.x; i < partial_count; i += kMergeThreads)
    {
        sum += partials[blockIdx.x + i * kHistogramBins];
    }

    __shared__ std::uint32_t data[kMergeThreads];
    data[threadIdx.x] = sum;
    for(unsigned stride = kMergeThreads / 2; stride > 0; stride >>= 1)
    {
        cg::sync(cta);
        if(threadIdx.x < stride)
        {
            data[threadIdx.x] += data[threadIdx.x + stride];
        }
    }
    if(threadIdx.x == 0)
    {
        hist[blockIdx.x] = data[0];
    }
}
} // namespace

void histogram256(const std::uint32_t *bins, std::size_t n, std::uint32_t *hist, Arena &arena, cudaStream_t stream)
{
    const unsigned partial_count = static_cast<unsigned>(std::clamp<std::size_t>(div_round_up<std::size_t>(n, kHistThreads * 16), 1, kMaxPartials));
    std::uint32_t *partials      = arena.allocate<std::uint32_t>(static_cast<std::size_t>(partial_count) * kHistogramBins);
    launch(histogram256_kernel, LaunchConfig{dim3(partial_count), dim3(kHistThreads), 0, stream}, partials, bins, static_cast<std::uint64_t>(n));
    launch(merge_histogram256_kernel, LaunchConfig{dim3(kHistogramBins), dim3(kMergeThreads), 0, stream}, hist, partials, partial_count);
}
} // namespace tsr::prims
// Tessera - stable LSD radix sort of key/value pairs.
//
// Each pass sorts on a 4-bit digit in three steps:
//   upsweep    per-tile digit counts, stored digit-major so that one exclusive
//              scan turns them into global scatter offsets
//   scan       prims::exclusive_scan over 16 * num_tiles counters
//   downsweep  ranks every key within its tile and scatters it
//
// Ranking is stable without block-wide scans: a tile is split into one
// contiguous 128-key chunk per warp, chunks are processed 32 keys at a time in
// order, and lanes holding equal digits are found with one ballot per digit
// bit. Per-warp running digit counts live in shared memory and are folded
// across warps once per tile.
//
// Real CUDA builds hand large sorts to CUB's onesweep radix sort instead (the
// path production renderers ship); the hand-written passes above remain the
// implementation on the emulated backend.
#include <algorithm>

#if defined(__CUDACC__)
#    include <cub/device/device_radix_sort.cuh>
#endif

#include "tsr/prims/prims.h"
#include "tsr/prims/warp.cuh"

namespace tsr::prims
{
namespace
{
constexpr int kRadixBits          = 4;
constexpr unsigned kRadixDigits   = 1u << kRadixBits;
constexpr unsigned kSortThreads   = 256;
constexpr unsigned kSortItems     = 4;
constexpr unsigned kSortWarps     = kSortThreads / kWarpSize;
constexpr unsigned kSortWarpChunk = kWarpSize * kSortItems;
constexpr unsigned kSortTile      = kSortThreads * kSortItems;

template<typename K>
TSR_DI unsigned digit_of(K key, int shift, unsigned digit_mask)
{
    return static_cast<unsigned>(key >> shift) & digit_mask;
}

template<typename K>
__global__ void __launch_bounds__(kSortThreads) radix_upsweep_kernel(
    const K *__restrict__ keys,
    std::uint64_t n,
    int shift,
    unsigned digit_mask,
    std::uint32_t *__restrict__ counts, // [kRadixDigits][num_tiles]
    unsigned num_tiles
)
{
    __shared__ std::uint32_t s_counts[kRadixDigits];
    if(threadIdx.x < kRadixDigits)
    {
        s_counts[threadIdx.x] = 0;
    }
    __syncthreads();

    const std::uint64_t base = static_cast<std::uint64_t>(blockIdx.x) * kSortTile;
    TSR_UNROLL
    for(unsigned k = 0; k < kSortItems; ++k)
    {
        const std::uint64_t idx = base + k * kSortThreads + threadIdx.x;
        if(idx < n)
        {
            atomicAdd(&s_counts[digit_of(keys[idx], shift, digit_mask)], 1u);
        }
    }
    __syncthreads();

    if(threadIdx.x < kRadixDigits)
    {
        counts[threadIdx.x * num_tiles + blockIdx.x] = s_counts[threadIdx.x];
    }
}

template<typename K, typename V>
__global__ void __launch_bounds__(kSortThreads) radix_downsweep_kernel(
    const K *__restrict__ keys_in,
    K *__restrict__ keys_out,
    const V *__restrict__ values_in,
    V *__restrict__ values_out,
    std::uint64_t n,
    int shift,
    unsigned digit_mask,
    const std::uint32_t *__restrict__ offsets, // exclusive scan of the upsweep counts
    unsigned num_tiles
)
{
    __shared__ std::uint32_t s_warp_counts[kSortWarps][kRadixDigits];
    const unsigned lane = lane_id();
    const unsigned warp = warp_id();
    if(lane < kRadixDigits)
    {
        s_warp_counts[warp][lane] = 0;
    }
    __syncwarp();

    const std::uint64_t chunk = static_cast<std::uint64_t>(blockIdx.x) * kSortTile + warp * kSortWarpChunk;
    K keys[kSortItems];
    V values[kSortItems];
    unsigned digits[kSortItems];
    std::uint32_t ranks[kSortItems];
    bool valid[kSortItems];

    TSR_UNROLL
    for(unsigned k = 0; k < kSortItems; ++k)
    {
        const std::uint64_t idx = chunk + k * kWarpSize + lane;
        valid[k]                = idx < n;
        digits[k]               = 0;
        ranks[k]                = 0;
        if(valid[k])
        {
            keys[k]   = keys_in[idx];
            values[k] = values_in[idx];
            digits[k] = digit_of(keys[k], shift, digit_mask);
        }

        const unsigned peers     = warp_match_label<kRadixBits>(digits[k], valid[k]);
        std::uint32_t warp_count = 0;
        if(valid[k])
        {
            warp_count = s_warp_counts[warp][digits[k]];
            ranks[k]   = warp_count + static_cast<std::uint32_t>(__popc(peers & lanemask_lt()));
        }
        __syncwarp();
        // The lowest lane of each peer group advances the group's counter.
        if(valid[k] && lane == static_cast<unsigned>(__ffs(static_cast<int>(peers)) - 1))
        {
            s_warp_counts[warp][digits[k]] = warp_count + static_cast<std::uint32_t>(__popc(peers));
        }
        __syncwarp();
    }
    __syncthreads();

    // Exclusive scan across warps for each digit: warp w's keys of digit d go
    // after every earlier warp's keys of digit d.
    if(threadIdx.x < kRadixDigits)
    {
        std::uint32_t running = 0;
        for(unsigned w = 0; w < kSortWarps; ++w)
        {
            const std::uint32_t c          = s_warp_counts[w][threadIdx.x];
            s_warp_counts[w][threadIdx.x]  = running;
            running                       += c;
        }
    }
    __syncthreads();

    TSR_UNROLL
    for(unsigned k = 0; k < kSortItems; ++k)
    {
        if(valid[k])
        {
            const std::uint32_t pos = offsets[digits[k] * num_tiles + blockIdx.x] + s_warp_counts[warp][digits[k]] + ranks[k];
            keys_out[pos]           = keys[k];
            values_out[pos]         = values[k];
        }
    }
}
} // namespace

template<typename K, typename V>
void radix_sort_pairs(
    const K *keys_in,
    K *keys_out,
    const V *values_in,
    V *values_out,
    std::size_t n,
    int begin_bit,
    int end_bit,
    Arena &arena,
    cudaStream_t stream
)
{
    TSR_CHECK(begin_bit >= 0 && end_bit <= static_cast<int>(8 * sizeof(K)) && begin_bit <= end_bit,
              "invalid bit range [" << begin_bit << ", " << end_bit << ")");
    TSR_CHECK(keys_in != keys_out && values_in != values_out, "radix_sort_pairs does not sort in place");
    if(n == 0)
    {
        return;
    }
    TSR_CHECK(n <= 0xffffffffu, "radix_sort_pairs supports at most 2^32-1 elements");

    const int passes = div_round_up(end_bit - begin_bit, kRadixBits);
    if(passes == 0)
    {
        TSR_CUDA_CHECK(cudaMemcpyAsync(keys_out, keys_in, n * sizeof(K), cudaMemcpyDeviceToDevice, stream));
        TSR_CUDA_CHECK(cudaMemcpyAsync(values_out, values_in, n * sizeof(V), cudaMemcpyDeviceToDevice, stream));
        return;
    }

#if defined(TSR_BACKEND_CUDA)
    std::size_t temp_bytes = 0;
    TSR_CUDA_CHECK(cub::DeviceRadixSort::SortPairs(nullptr, temp_bytes, keys_in, keys_out, values_in, values_out,
                                                   static_cast<std::uint32_t>(n), begin_bit, end_bit, stream));
    void *temp = arena.allocate_bytes(temp_bytes);
    TSR_CUDA_CHECK(cub::DeviceRadixSort::SortPairs(temp, temp_bytes, keys_in, keys_out, values_in, values_out,
                                                   static_cast<std::uint32_t>(n), begin_bit, end_bit, stream));
    return;
#endif

    const unsigned num_tiles = static_cast<unsigned>(div_round_up<std::size_t>(n, kSortTile));
    std::uint32_t *counts    = arena.allocate<std::uint32_t>(static_cast<std::size_t>(kRadixDigits) * num_tiles);
    K *tmp_keys              = passes > 1 ? arena.allocate<K>(n) : nullptr;
    V *tmp_values            = passes > 1 ? arena.allocate<V>(n) : nullptr;

    const K *src_keys   = keys_in;
    const V *src_values = values_in;
    for(int p = 0; p < passes; ++p)
    {
        // Alternate destinations so that the final pass lands in the outputs.
        const bool to_out    = ((passes - 1 - p) % 2) == 0;
        K *dst_keys          = to_out ? keys_out : tmp_keys;
        V *dst_values        = to_out ? values_out : tmp_values;
        const int shift      = begin_bit + p * kRadixBits;
        const int bits       = std::min(kRadixBits, end_bit - shift);
        const unsigned dmask = (1u << bits) - 1u;

        launch(
            radix_upsweep_kernel<K>,
            LaunchConfig{dim3(num_tiles), dim3(kSortThreads), 0, stream},
            src_keys,
            static_cast<std::uint64_t>(n),
            shift,
            dmask,
            counts,
            num_tiles
        );
        exclusive_scan(counts, counts, static_cast<std::size_t>(kRadixDigits) * num_tiles, arena, stream);
        launch(
            radix_downsweep_kernel<K, V>,
            LaunchConfig{dim3(num_tiles), dim3(kSortThreads), 0, stream},
            src_keys,
            dst_keys,
            src_values,
            dst_values,
            static_cast<std::uint64_t>(n),
            shift,
            dmask,
            counts,
            num_tiles
        );
        src_keys   = dst_keys;
        src_values = dst_values;
    }
}

template<typename K, typename V>
void sort_pairs(
    const K *keys_in,
    K *keys_out,
    const V *values_in,
    V *values_out,
    std::size_t n,
    int begin_bit,
    int end_bit,
    Arena &arena,
    cudaStream_t stream
)
{
    if(n <= kBitonicMaxElements)
    {
        // A single shared-memory network beats several radix passes for
        // small inputs. It compares whole keys, which matches the radix
        // ordering because callers only set bits inside [begin_bit, end_bit).
        bitonic_sort_pairs(keys_in, keys_out, values_in, values_out, n, stream);
        return;
    }
    radix_sort_pairs(keys_in, keys_out, values_in, values_out, n, begin_bit, end_bit, arena, stream);
}

#define TSR_INSTANTIATE_SORT(K, V)                                                                                  \
    template void radix_sort_pairs<K, V>(const K *, K *, const V *, V *, std::size_t, int, int, Arena &, cudaStream_t); \
    template void sort_pairs<K, V>(const K *, K *, const V *, V *, std::size_t, int, int, Arena &, cudaStream_t);

TSR_INSTANTIATE_SORT(std::uint64_t, std::int32_t)
TSR_INSTANTIATE_SORT(std::uint32_t, std::uint32_t)
TSR_INSTANTIATE_SORT(std::uint32_t, std::int32_t)

#undef TSR_INSTANTIATE_SORT
} // namespace tsr::prims
// Tessera - single-block bitonic sort for short key/value arrays.
//
// After bitonicSortShared from the cuda-samples "sortingNetworks" sample
// (BSD-3-Clause). Changes: templated key/value types, arbitrary lengths up to
// the shared-memory limit (padded with maximal sentinels to the next power of
// two), and a comparator that orders by (key, value) so equal keys come out in
// a deterministic order.
#include <limits>

#include "tsr/prims/prims.h"

namespace tsr::prims
{
namespace
{
constexpr unsigned kSharedSizeLimit = static_cast<unsigned>(kBitonicMaxElements);

template<typename K, typename V>
TSR_DI void comparator(K &key_a, V &val_a, K &key_b, V &val_b, unsigned dir)
{
    const bool a_greater = key_a > key_b || (key_a == key_b && val_a > val_b);
    if(a_greater == (dir != 0))
    {
        const K tk = key_a;
        key_a      = key_b;
        key_b      = tk;
        const V tv = val_a;
        val_a      = val_b;
        val_b      = tv;
    }
}

template<typename K, typename V>
__global__ void bitonic_sort_shared_kernel(
    const K *__restrict__ keys_in,
    K *__restrict__ keys_out,
    const V *__restrict__ values_in,
    V *__restrict__ values_out,
    unsigned n,
    unsigned array_length, // power of two >= n
    unsigned dir           // 1 = ascending
)
{
    cg::thread_block cta = cg::this_thread_block();
    __shared__ K s_key[kSharedSizeLimit];
    __shared__ V s_val[kSharedSizeLimit];

    const unsigned half = array_length / 2;
    const unsigned t    = threadIdx.x;
    TSR_UNROLL
    for(unsigned j = 0; j < 2; ++j)
    {
        const unsigned i = t + j * half;
        if(i < n)
        {
            s_key[i] = keys_in[i];
            s_val[i] = values_in[i];
        }
        else
        {
            s_key[i] = std::numeric_limits<K>::max();
            s_val[i] = std::numeric_limits<V>::max();
        }
    }

    for(unsigned size = 2; size < array_length; size <<= 1)
    {
        // Bitonic merge
        const unsigned ddd = dir ^ ((t & (size / 2)) != 0);
        for(unsigned stride = size / 2; stride > 0; stride >>= 1)
        {
            cg::sync(cta);
            const unsigned pos = 2 * t - (t & (stride - 1));
            comparator(s_key[pos], s_val[pos], s_key[pos + stride], s_val[pos + stride], ddd);
        }
    }

    // ddd == dir for the last bitonic merge step
    for(unsigned stride = array_length / 2; stride > 0; stride >>= 1)
    {
        cg::sync(cta);
        const unsigned pos = 2 * t - (t & (stride - 1));
        comparator(s_key[pos], s_val[pos], s_key[pos + stride], s_val[pos + stride], dir);
    }

    cg::sync(cta);
    TSR_UNROLL
    for(unsigned j = 0; j < 2; ++j)
    {
        const unsigned i = t + j * half;
        if(i < n)
        {
            keys_out[i]   = s_key[i];
            values_out[i] = s_val[i];
        }
    }
}
} // namespace

template<typename K, typename V>
void bitonic_sort_pairs(const K *keys_in, K *keys_out, const V *values_in, V *values_out, std::size_t n, cudaStream_t stream)
{
    TSR_CHECK(n <= kBitonicMaxElements, "bitonic_sort_pairs handles at most " << kBitonicMaxElements << " elements, got " << n);
    if(n == 0)
    {
        return;
    }
    unsigned length = 2;
    while(length < n)
    {
        length <<= 1;
    }
    launch(
        bitonic_sort_shared_kernel<K, V>,
        LaunchConfig{dim3(1), dim3(length / 2), 0, stream},
        keys_in,
        keys_out,
        values_in,
        values_out,
        static_cast<unsigned>(n),
        length,
        1u
    );
}

template void bitonic_sort_pairs<std::uint64_t, std::int32_t>(const std::uint64_t *, std::uint64_t *, const std::int32_t *, std::int32_t *, std::size_t, cudaStream_t);
template void bitonic_sort_pairs<std::uint32_t, std::uint32_t>(const std::uint32_t *, std::uint32_t *, const std::uint32_t *, std::uint32_t *, std::size_t, cudaStream_t);
template void bitonic_sort_pairs<std::uint32_t, std::int32_t>(const std::uint32_t *, std::uint32_t *, const std::int32_t *, std::int32_t *, std::size_t, cudaStream_t);
} // namespace tsr::prims
// Tessera - stream compaction of index sets.
#include "tsr/prims/prims.h"

namespace tsr::prims
{
namespace
{
__global__ void flags_to_counts_kernel(std::uint64_t n, const std::uint8_t *__restrict__ flags, std::uint32_t *__restrict__ counts)
{
    const std::uint64_t i = static_cast<std::uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if(i < n)
    {
        counts[i] = flags[i] != 0 ? 1u : 0u;
    }
}

__global__ void scatter_indices_kernel(
    std::uint64_t n,
    const std::uint8_t *__restrict__ flags,
    const std::uint32_t *__restrict__ positions,
    std::uint32_t *__restrict__ out
)
{
    const std::uint64_t i = static_cast<std::uint64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if(i < n && flags[i] != 0)
    {
        out[positions[i]] = static_cast<std::uint32_t>(i);
    }
}
} // namespace

std::uint32_t compact_indices(const std::uint8_t *flags, std::size_t n, std::uint32_t *out_indices, Arena &arena, cudaStream_t stream)
{
    if(n == 0)
    {
        return 0;
    }
    TSR_CHECK(n <= 0xffffffffu, "compact_indices supports at most 2^32-1 elements");
    std::uint32_t *positions = arena.allocate<std::uint32_t>(n);
    const auto count         = static_cast<std::uint32_t>(n);
    launch_linear(flags_to_counts_kernel, count, stream, static_cast<std::uint64_t>(n), flags, positions);
    const std::uint32_t total = exclusive_scan_total(positions, positions, n, arena, stream);
    launch_linear(scatter_indices_kernel, count, stream, static_cast<std::uint64_t>(n), flags, positions, out_indices);
    return total;
}
} // namespace tsr::prims

// Tessera - binning of screen-space splats into image tiles.
//
// Two-pass intersection after gsplat's intersect_tile_kernel (Apache-2.0):
// pass one counts the tiles each splat overlaps, a prefix sum turns counts
// into write offsets, pass two emits the keys. The accurate path uses the
// SnugBox bound and AccuTile per-column ellipse clipping from SpeedySplat
// (arXiv:2412.00578) as implemented in gsplat; the offsets kernel follows
// gsplat's intersect_offset_kernel.
#include "tsr/bin/tiles.h"
#include "tsr/geom/gaussian_math.cuh"
#include "tsr/prims/prims.h"

namespace tsr
{
namespace
{
TSR_DI float2 ellipse_intersection(float A, float B, float C, float disc, float t, float2 p, bool is_y, float coord)
{
    const float p_u       = is_y ? p.y : p.x;
    const float p_v       = is_y ? p.x : p.y;
    const float coeff     = is_y ? A : C;
    const float h         = coord - p_u;
    const float sqrt_term = sqrtf(disc * h * h + t * coeff);
    return make_float2((-B * h - sqrt_term) / coeff + p_v, (-B * h + sqrt_term) / coeff + p_v);
}

// Walks the columns (or rows when is_y) of the tile rectangle and, for each,
// the range of tiles the ellipse covers. Counts them and, if keys != nullptr,
// emits one intersection per tile.
TSR_DI std::uint32_t accutile_tiles(
    float A,
    float B,
    float C,
    float disc,
    float t,
    float2 p,
    float2 bbox_min,
    float2 bbox_max,
    float2 bbox_argmin,
    float2 bbox_argmax,
    int2 rect_min,
    int2 rect_max,
    std::uint32_t tile_size,
    std::uint32_t tiles_x,
    bool is_y,
    std::uint64_t depth_bits,
    std::int32_t splat,
    std::uint64_t *keys,
    std::int32_t *ids,
    std::int64_t cursor
)
{
    const float block = static_cast<float>(tile_size);
    if(is_y)
    {
        rect_min    = make_int2(rect_min.y, rect_min.x);
        rect_max    = make_int2(rect_max.y, rect_max.x);
        bbox_min    = make_float2(bbox_min.y, bbox_min.x);
        bbox_max    = make_float2(bbox_max.y, bbox_max.x);
        bbox_argmin = make_float2(bbox_argmin.y, bbox_argmin.x);
        bbox_argmax = make_float2(bbox_argmax.y, bbox_argmax.x);
    }

    std::uint32_t count = 0;
    float2 intersect_max_line = make_float2(bbox_max.y, bbox_min.y);
    float min_line            = rect_min.x * block;
    float2 intersect_min_line = bbox_min.x <= min_line ? ellipse_intersection(A, B, C, disc, t, p, is_y, min_line) : intersect_max_line;

    TSR_NO_UNROLL
    for(int u = rect_min.x; u < rect_max.x; ++u)
    {
        const float max_line = min_line + block;
        if(max_line <= bbox_max.x)
        {
            intersect_max_line = ellipse_intersection(A, B, C, disc, t, p, is_y, max_line);
        }
        const float ellipse_min = (min_line <= bbox_argmin.y && bbox_argmin.y < max_line)
                                    ? bbox_min.y
                                    : fminf(intersect_min_line.x, intersect_max_line.x);
        const float ellipse_max = (min_line <= bbox_argmax.y && bbox_argmax.y < max_line)
                                    ? bbox_max.y
                                    : fmaxf(intersect_min_line.y, intersect_max_line.y);

        const int min_tile_v = max(rect_min.y, min(rect_max.y, static_cast<int>(ellipse_min / block)));
        const int max_tile_v = min(rect_max.y, max(rect_min.y, static_cast<int>(ellipse_max / block + 1)));

        TSR_NO_UNROLL
        for(int v = min_tile_v; v < max_tile_v; ++v)
        {
            const std::uint64_t tile_id = is_y ? static_cast<std::uint64_t>(u) * tiles_x + v : static_cast<std::uint64_t>(v) * tiles_x + u;
            if(keys != nullptr)
            {
                keys[cursor + count] = (tile_id << 32) | depth_bits;
                ids[cursor + count]  = splat;
            }
            ++count;
        }
        intersect_min_line = intersect_max_line;
        min_line           = max_line;
    }
    return count;
}

// first pass (keys == nullptr): tiles_per_splat[i] = overlap count
// second pass: emit keys at [cum[i] - count, cum[i])
__global__ void intersect_tiles_kernel(
    std::uint32_t n,
    const int2 *__restrict__ radii,
    const float2 *__restrict__ means2d,
    const float *__restrict__ depths,
    const float3 *__restrict__ conics,
    const float *__restrict__ opacities,
    std::uint32_t tile_size,
    std::uint32_t tiles_x,
    std::uint32_t tiles_y,
    bool accurate,
    std::int64_t *__restrict__ tiles_per_splat, // counts (pass 1) or inclusive cumsum (pass 2)
    std::uint64_t *__restrict__ keys,
    std::int32_t *__restrict__ ids
)
{
    const std::uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx >= n)
    {
        return;
    }
    const bool first_pass = keys == nullptr;
    const int2 radius     = radii[idx];
    if(radius.x <= 0 || radius.y <= 0)
    {
        if(first_pass)
        {
            tiles_per_splat[idx] = 0;
        }
        return;
    }

    const float2 mean2d          = means2d[idx];
    const std::int64_t cursor    = first_pass ? 0 : (idx == 0 ? 0 : tiles_per_splat[idx - 1]);
    const std::uint64_t depth_id = first_pass ? 0 : static_cast<std::uint64_t>(__float_as_uint(depths[idx]));
    const float tile_size_f      = static_cast<float>(tile_size);

    if(accurate)
    {
        // conic = (a, b, c): upper triangle of Sigma^{-1}; quadratic form
        // q = a dx^2 + 2 b dx dy + c dy^2 and disc = b^2 - a c = -det(Sigma^{-1}).
        const float3 conic = conics[idx];
        const float A = conic.x, B = conic.y, C = conic.z;
        const float disc = B * B - A * C;
        // opacity-aware level set alpha >= threshold, capped like the radius
        const float t = fminf(geom::kGaussianExtent * geom::kGaussianExtent, 2.0f * __logf(opacities[idx] / geom::kAlphaThreshold));

        const float neg_t_over_disc = -t / disc;
        const float x_extent        = sqrtf(neg_t_over_disc * C);
        const float y_extent        = sqrtf(neg_t_over_disc * A);
        const float2 bbox_min       = make_float2(mean2d.x - x_extent, mean2d.y - y_extent);
        const float2 bbox_max       = make_float2(mean2d.x + x_extent, mean2d.y + y_extent);
        const float bx_over_c       = B * x_extent / C;
        const float by_over_a       = B * y_extent / A;
        const float2 bbox_argmin    = make_float2(mean2d.y + bx_over_c, mean2d.x + by_over_a);
        const float2 bbox_argmax    = make_float2(mean2d.y - bx_over_c, mean2d.x - by_over_a);

        const int2 rect_min = make_int2(
            max(0, min(static_cast<int>(tiles_x), static_cast<int>(bbox_min.x / tile_size_f))),
            max(0, min(static_cast<int>(tiles_y), static_cast<int>(bbox_min.y / tile_size_f)))
        );
        const int2 rect_max = make_int2(
            max(0, min(static_cast<int>(tiles_x), static_cast<int>(bbox_max.x / tile_size_f + 1.f))),
            max(0, min(static_cast<int>(tiles_y), static_cast<int>(bbox_max.y / tile_size_f + 1.f)))
        );
        const int y_span = rect_max.y - rect_min.y;
        const int x_span = rect_max.x - rect_min.x;
        if(y_span * x_span == 0)
        {
            if(first_pass)
            {
                tiles_per_splat[idx] = 0;
            }
            return;
        }
        const std::uint32_t count = accutile_tiles(
            A, B, C, disc, t, mean2d, bbox_min, bbox_max, bbox_argmin, bbox_argmax, rect_min, rect_max,
            tile_size, tiles_x, y_span < x_span, depth_id, static_cast<std::int32_t>(idx), keys, ids, cursor
        );
        if(first_pass)
        {
            tiles_per_splat[idx] = count;
        }
        return;
    }

    // Axis-aligned fallback. tile_min is inclusive, tile_max exclusive.
    const float tile_radius_x = radius.x / tile_size_f;
    const float tile_radius_y = radius.y / tile_size_f;
    const float tile_x        = mean2d.x / tile_size_f;
    const float tile_y        = mean2d.y / tile_size_f;
    const int2 tile_min       = make_int2(
        min(max(0, static_cast<int>(floorf(tile_x - tile_radius_x))), static_cast<int>(tiles_x)),
        min(max(0, static_cast<int>(floorf(tile_y - tile_radius_y))), static_cast<int>(tiles_y))
    );
    const int2 tile_max = make_int2(
        min(max(0, static_cast<int>(ceilf(tile_x + tile_radius_x))), static_cast<int>(tiles_x)),
        min(max(0, static_cast<int>(ceilf(tile_y + tile_radius_y))), static_cast<int>(tiles_y))
    );
    if(first_pass)
    {
        tiles_per_splat[idx] = static_cast<std::int64_t>(tile_max.y - tile_min.y) * (tile_max.x - tile_min.x);
        return;
    }
    std::int64_t cur = cursor;
    for(int i = tile_min.y; i < tile_max.y; ++i)
    {
        for(int j = tile_min.x; j < tile_max.x; ++j)
        {
            const std::uint64_t tile_id = static_cast<std::uint64_t>(i) * tiles_x + j;
            keys[cur]                   = (tile_id << 32) | depth_id;
            ids[cur]                    = static_cast<std::int32_t>(idx);
            ++cur;
        }
    }
}

// e.g. tile ids of sorted keys: [1, 1, 1, 3, 3], n_tiles = 6
//      offsets:                 [0, 0, 3, 3, 5, 5, 5]
__global__ void tile_offsets_kernel(
    std::uint32_t n_isects,
    const std::uint64_t *__restrict__ sorted_keys,
    std::uint32_t n_tiles,
    std::int32_t *__restrict__ offsets // [n_tiles + 1]
)
{
    const std::uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx >= n_isects)
    {
        return;
    }
    const std::int64_t tile_curr = static_cast<std::int64_t>(sorted_keys[idx] >> 32);
    if(idx == 0)
    {
        // offsets up to and including the first occupied tile
        for(std::int64_t i = 0; i < tile_curr + 1; ++i)
        {
            offsets[i] = 0;
        }
    }
    if(idx == n_isects - 1)
    {
        // every later tile, plus the terminating entry
        for(std::int64_t i = tile_curr + 1; i <= static_cast<std::int64_t>(n_tiles); ++i)
        {
            offsets[i] = static_cast<std::int32_t>(n_isects);
        }
    }
    if(idx > 0)
    {
        const std::int64_t tile_prev = static_cast<std::int64_t>(sorted_keys[idx - 1] >> 32);
        if(tile_prev == tile_curr)
        {
            return;
        }
        for(std::int64_t i = tile_prev + 1; i < tile_curr + 1; ++i)
        {
            offsets[i] = static_cast<std::int32_t>(idx);
        }
    }
}
} // namespace

std::uint32_t tile_id_bits(std::uint32_t n_tiles)
{
    std::uint32_t bits = 0;
    while(bits < 32 && (std::uint64_t{1} << bits) < n_tiles)
    {
        ++bits;
    }
    return bits;
}

void bin_splats(
    const ProjectedSplats &splats,
    const Camera &camera,
    const BinningSettings &settings,
    TileBinning &out,
    Arena &arena,
    cudaStream_t stream
)
{
    TSR_CHECK(settings.tile_size > 0 && (settings.tile_size & (settings.tile_size - 1)) == 0,
              "tile size must be a power of two, got " << settings.tile_size);
    out.tile_size = settings.tile_size;
    out.tiles_x   = camera.tiles_x(settings.tile_size);
    out.tiles_y   = camera.tiles_y(settings.tile_size);
    out.tile_bits = tile_id_bits(out.n_tiles());
    TSR_CHECK(out.tile_bits <= 32, "too many tiles: " << out.n_tiles());

    const std::uint32_t n = splats.count;
    out.tiles_per_splat.resize(n);
    out.tile_offsets.resize(static_cast<std::size_t>(out.n_tiles()) + 1);

    // pass 1: count
    launch_linear(
        intersect_tiles_kernel, n, stream, n, splats.radii.data(), splats.means2d.data(), splats.depths.data(),
        splats.conics.data(), splats.opacities.data(), out.tile_size, out.tiles_x, out.tiles_y, settings.accurate,
        out.tiles_per_splat.data(), static_cast<std::uint64_t *>(nullptr), static_cast<std::int32_t *>(nullptr)
    );

    std::int64_t total = 0;
    if(n > 0)
    {
        prims::inclusive_scan(out.tiles_per_splat.data(), out.tiles_per_splat.data(), n, arena, stream);
        TSR_CUDA_CHECK(cudaMemcpyAsync(&total, out.tiles_per_splat.data() + n - 1, sizeof(total), cudaMemcpyDeviceToHost, stream));
        TSR_CUDA_CHECK(cudaStreamSynchronize(stream));
    }
    TSR_CHECK(total < 0x7fffffff, "intersection count overflow: " << total);
    out.n_isects = static_cast<std::uint32_t>(total);

    if(out.n_isects == 0)
    {
        out.tile_offsets.zero(stream);
        out.keys.resize(0);
        out.splat_ids.resize(0);
        out.sorted_keys.resize(0);
        out.sorted_splat_ids.resize(0);
        return;
    }

    // pass 2: emit
    out.keys.resize(out.n_isects);
    out.splat_ids.resize(out.n_isects);
    launch_linear(
        intersect_tiles_kernel, n, stream, n, splats.radii.data(), splats.means2d.data(), splats.depths.data(),
        splats.conics.data(), splats.opacities.data(), out.tile_size, out.tiles_x, out.tiles_y, settings.accurate,
        out.tiles_per_splat.data(), out.keys.data(), out.splat_ids.data()
    );

    // group by tile, front to back within a tile
    out.sorted_keys.resize(out.n_isects);
    out.sorted_splat_ids.resize(out.n_isects);
    prims::sort_pairs(
        out.keys.data(), out.sorted_keys.data(), out.splat_ids.data(), out.sorted_splat_ids.data(), out.n_isects, 0,
        32 + static_cast<int>(out.tile_bits), arena, stream
    );

    launch_linear(tile_offsets_kernel, out.n_isects, stream, out.n_isects, out.sorted_keys.data(), out.n_tiles(), out.tile_offsets.data());
}
} // namespace tsr
// Tessera - coarse binning of mesh faces.
//
// Derived from PyTorch3D's coarse rasterizer (rasterize_coarse.cu and
// bitmask.cuh, BSD-3-Clause, Copyright Meta Platforms, Inc. and affiliates),
// reduced to a single image. Each block takes a chunk of faces, marks every
// (bin, face) overlap in a shared-memory bit mask, then reserves space in each
// bin with one global atomic per bin and writes the chunk's faces out.
#include <algorithm>

#include "tsr/bin/mesh_bins.h"
#include "tsr/geom/mesh_ndc.cuh"

namespace tsr
{
namespace
{
constexpr float kFaceEpsilon  = 1e-8f;
constexpr int kMaxChunkSize   = 512;  // faces per coarse-binning chunk
constexpr int kCoarseSmemBytes = 96 * 1024; // bit-mask budget per block (sm_80+ opt-in limit is 99 KiB)
constexpr int kCoarseThreads  = 512;
constexpr int kCoarseBlocks   = 64;
constexpr int kMaxBinsPerSide = 22 * 4;

// A bool array of shape (H, W, N) packed into 32-bit words in shared memory.
class BitMask
{
public:
    TSR_DI BitMask(unsigned *data, int H, int W, int N) : data_(data), H_(H), W_(W), D_(N / 32) {}

    // Use all threads in the block to clear every bit.
    TSR_DI void block_clear()
    {
        for(int i = static_cast<int>(threadIdx.x); i < H_ * W_ * D_; i += static_cast<int>(blockDim.x))
        {
            data_[i] = 0;
        }
        __syncthreads();
    }

    TSR_DI void set(int y, int x, int d) { atomicOr(data_ + elem(y, x, d), 1u << (d % 32)); }

    TSR_DI bool get(int y, int x, int d) const { return (data_[elem(y, x, d)] >> (d % 32)) & 1u; }

    // Number of set bits in row (y, x, :).
    TSR_DI int count(int y, int x) const
    {
        int total = 0;
        for(int i = 0; i < D_; ++i)
        {
            total += __popc(data_[y * W_ * D_ + x * D_ + i]);
        }
        return total;
    }

private:
    TSR_DI int elem(int y, int x, int d) const { return y * W_ * D_ + x * D_ + d / 32; }

    unsigned *data_;
    int H_, W_, D_;
};

__global__ void triangle_bounding_box_kernel(
    const float3 *__restrict__ face_verts, // [F][3]
    int F,
    float blur_radius,
    float4 *__restrict__ bboxes, // [F] (xmin, xmax, ymin, ymax)
    std::uint8_t *__restrict__ skip_face
)
{
    const int f = static_cast<int>(blockIdx.x * blockDim.x + threadIdx.x);
    if(f >= F)
    {
        return;
    }
    const float sqrt_radius = sqrtf(blur_radius);
    const float3 v0         = face_verts[3 * f + 0];
    const float3 v1         = face_verts[3 * f + 1];
    const float3 v2         = face_verts[3 * f + 2];
    const float xmin        = fminf(v0.x, fminf(v1.x, v2.x)) - sqrt_radius;
    const float xmax        = fmaxf(v0.x, fmaxf(v1.x, v2.x)) + sqrt_radius;
    const float ymin        = fminf(v0.y, fminf(v1.y, v2.y)) - sqrt_radius;
    const float ymax        = fmaxf(v0.y, fmaxf(v1.y, v2.y)) + sqrt_radius;
    const float zmin        = fminf(v0.z, fminf(v1.z, v2.z));
    bboxes[f]               = make_float4(xmin, xmax, ymin, ymax);
    skip_face[f]            = zmin < kFaceEpsilon ? 1 : 0; // behind or touching the camera plane
}

__global__ void __launch_bounds__(kCoarseThreads) rasterize_coarse_kernel(
    const float4 *__restrict__ bboxes,
    const std::uint8_t *__restrict__ should_skip,
    int E,
    int H,
    int W,
    int bin_size,
    int max_elem_per_bin,
    int chunk_size,                           // multiple of 32
    std::int32_t *__restrict__ elems_per_bin, // [BH][BW]
    std::int32_t *__restrict__ bin_elems,     // [BH][BW][M]
    int *__restrict__ overflow_flag
)
{
    TSR_DYNAMIC_SMEM(unsigned, sbuf);
    const int M          = max_elem_per_bin;
    const int num_bins_x = 1 + (W - 1) / bin_size;
    const int num_bins_y = 1 + (H - 1) / bin_size;

    // Size of half a pixel in NDC units.
    const float half_pix_x = geom::non_square_ndc_range(W, H) / 2.0f / W;
    const float half_pix_y = geom::non_square_ndc_range(H, W) / 2.0f / H;

    BitMask binmask(sbuf, num_bins_y, num_bins_x, chunk_size);
    const int num_chunks = 1 + (E - 1) / chunk_size;

    for(int chunk = static_cast<int>(blockIdx.x); chunk < num_chunks; chunk += static_cast<int>(gridDim.x))
    {
        const int chunk_start = chunk * chunk_size;
        binmask.block_clear();

        // One face per thread within the chunk.
        for(int e = static_cast<int>(threadIdx.x); e < chunk_size; e += static_cast<int>(blockDim.x))
        {
            const int e_idx = chunk_start + e;
            if(e_idx >= E || should_skip[e_idx])
            {
                continue;
            }
            const float4 bb = bboxes[e_idx];
            for(int by = 0; by < num_bins_y; ++by)
            {
                // pix_to_non_square_ndc gives pixel centres; widen by half a
                // pixel for the true extent of the bin.
                const float bin_y_min = geom::pix_to_non_square_ndc(by * bin_size, H, W) - half_pix_y;
                const float bin_y_max = geom::pix_to_non_square_ndc((by + 1) * bin_size - 1, H, W) + half_pix_y;
                const bool y_overlap  = (bb.z <= bin_y_max) && (bin_y_min < bb.w);
                for(int bx = 0; bx < num_bins_x; ++bx)
                {
                    const float bin_x_max = geom::pix_to_non_square_ndc((bx + 1) * bin_size - 1, W, H) + half_pix_x;
                    const float bin_x_min = geom::pix_to_non_square_ndc(bx * bin_size, W, H) - half_pix_x;
                    const bool x_overlap  = (bb.x <= bin_x_max) && (bin_x_min < bb.y);
                    if(y_overlap && x_overlap)
                    {
                        binmask.set(by, bx, e);
                    }
                }
            }
        }
        __syncthreads();

        // One bin per thread: reserve space for this chunk's faces with a
        // single global atomic, then write them in face order.
        for(int byx = static_cast<int>(threadIdx.x); byx < num_bins_y * num_bins_x; byx += static_cast<int>(blockDim.x))
        {
            const int by    = byx / num_bins_x;
            const int bx    = byx % num_bins_x;
            const int count = binmask.count(by, bx);
            if(count == 0)
            {
                continue;
            }
            const int start = atomicAdd(elems_per_bin + by * num_bins_x + bx, count);
            if(start + count > M)
            {
                atomicExch(overflow_flag, 1);
                continue;
            }
            int next_idx = by * num_bins_x * M + bx * M + start;
            for(int e = 0; e < chunk_size; ++e)
            {
                if(binmask.get(by, bx, e))
                {
                    bin_elems[next_idx] = chunk_start + e;
                    ++next_idx;
                }
            }
        }
        __syncthreads();
    }
}
} // namespace

void bin_mesh_faces(
    const ViewFaces &faces,
    int width,
    int height,
    const MeshBinningSettings &settings,
    MeshBins &out,
    Arena &arena,
    cudaStream_t stream
)
{
    TSR_CHECK(settings.bin_size > 0, "bin size must be positive");
    out.bin_size          = settings.bin_size;
    out.bins_x            = 1 + (width - 1) / settings.bin_size;
    out.bins_y            = 1 + (height - 1) / settings.bin_size;
    out.max_faces_per_bin = settings.max_faces_per_bin;
    out.overflowed        = false;
    TSR_CHECK(out.bins_x < kMaxBinsPerSide && out.bins_y < kMaxBinsPerSide,
              "too many bins (" << out.bins_x << " x " << out.bins_y << "); increase bin_size");

    const int n_bins = out.bins_x * out.bins_y;
    out.faces_per_bin.resize(static_cast<std::size_t>(n_bins));
    out.bin_faces.resize(static_cast<std::size_t>(n_bins) * settings.max_faces_per_bin);
    out.faces_per_bin.zero(stream);
    TSR_CUDA_CHECK(cudaMemsetAsync(out.bin_faces.data(), 0xff, out.bin_faces.bytes(), stream)); // -1 sentinels
    const int F = static_cast<int>(faces.n_faces);
    if(F == 0)
    {
        return;
    }

    float4 *bboxes      = arena.allocate<float4>(F);
    std::uint8_t *skip  = arena.allocate<std::uint8_t>(F);
    int *overflow_flag  = arena.allocate<int>(1);
    TSR_CUDA_CHECK(cudaMemsetAsync(overflow_flag, 0, sizeof(int), stream));
    launch_linear(triangle_bounding_box_kernel, static_cast<std::uint32_t>(F), stream, faces.ndc.data(), F, settings.blur_radius, bboxes, skip);

    // The bit mask holds n_bins x chunk bits; shrink the chunk for large bin
    // grids so that it fits the shared-memory budget.
    const int chunk = std::min(kMaxChunkSize, (kCoarseSmemBytes * 8 / n_bins) / 32 * 32);
    TSR_CHECK(chunk >= 32, "too many bins (" << out.bins_x << " x " << out.bins_y << ") for the coarse rasterizer; increase bin_size");
    const std::size_t smem = static_cast<std::size_t>(n_bins) * chunk / 8;
    const int blocks       = std::min(kCoarseBlocks, 1 + (F - 1) / chunk);
    TSR_CUDA_CHECK(cudaFuncSetAttribute(rasterize_coarse_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, static_cast<int>(smem)));
    launch(
        rasterize_coarse_kernel,
        LaunchConfig{dim3(blocks), dim3(kCoarseThreads), smem, stream},
        bboxes, skip, F, height, width, settings.bin_size, settings.max_faces_per_bin, chunk, out.faces_per_bin.data(),
        out.bin_faces.data(), overflow_flag
    );

    int overflow = 0;
    TSR_CUDA_CHECK(cudaMemcpyAsync(&overflow, overflow_flag, sizeof(int), cudaMemcpyDeviceToHost, stream));
    TSR_CUDA_CHECK(cudaStreamSynchronize(stream));
    out.overflowed = overflow != 0;
}
