// Tessera - tile-based compositing of splats over the surface layer.
//
// Derived from gsplat's rasterize_to_pixels_3dgs_fwd_kernel and the blending
// helpers in RasterizeToPixels3DGSDevice.cuh (Apache-2.0). Changes for
// Tessera: three colour channels, a per-pixel surface layer that both bounds
// the visible depth range and replaces the background, and a per-splat depth
// carried through the shared-memory batch.
#include "tsr/geom/gaussian_math.cuh"
#include "tsr/math/vec.h"
#include "tsr/raster/splat_raster.h"

namespace tsr
{
namespace
{
struct GaussianWeight
{
    float vis;   // exp(-sigma)
    float alpha; // min(kMaxAlpha, opacity * vis)
    bool valid;  // sigma >= 0 and alpha >= kAlphaThreshold
};

// sigma is the Mahalanobis exponent for the pixel offset (dx, dy) = mean - pixel.
TSR_DI GaussianWeight eval_gaussian_weight(const float3 &conic, float dx, float dy, float opac)
{
    const float sigma = 0.5f * (conic.x * dx * dx + conic.z * dy * dy) + conic.y * dx * dy;
    const float vis   = __expf(-sigma);
    const float alpha = fminf(geom::kMaxAlpha, opac * vis);
    return GaussianWeight{vis, alpha, !(sigma < 0.f || alpha < geom::kAlphaThreshold)};
}

template<std::uint32_t TILE_SIZE, std::uint32_t CTA_SIZE>
__global__ void __launch_bounds__(CTA_SIZE) rasterize_splats_kernel(
    const float2 *__restrict__ means2d,
    const float3 *__restrict__ conics,
    const float3 *__restrict__ colors,
    const float *__restrict__ opacities,
    const float *__restrict__ depths,
    const std::uint32_t image_width,
    const std::uint32_t image_height,
    const std::uint32_t tile_width,
    const std::int32_t *__restrict__ tile_offsets, // [n_tiles + 1]
    const std::int32_t *__restrict__ flatten_ids,  // [n_isects]
    const float3 *__restrict__ surface_color,      // [H][W]
    const float *__restrict__ surface_depth,       // [H][W]
    float3 *__restrict__ render_colors,            // [H][W]
    float *__restrict__ render_alphas,             // [H][W]
    std::int32_t *__restrict__ last_ids            // [H][W]
)
{
    constexpr std::uint32_t BATCH_SIZE        = CTA_SIZE;
    constexpr std::uint32_t PIXELS_PER_THREAD = TILE_SIZE * TILE_SIZE / CTA_SIZE;
    constexpr std::uint32_t ROW_STRIDE        = CTA_SIZE / TILE_SIZE;
    constexpr std::uint32_t TILE_MASK         = TILE_SIZE - 1;
    constexpr std::uint32_t TILE_SHIFT        = TILE_SIZE == 16 ? 4 : (TILE_SIZE == 8 ? 3 : 2);
    constexpr std::uint32_t ALL_DONE          = (1u << PIXELS_PER_THREAD) - 1u;
    static_assert((TILE_SIZE & (TILE_SIZE - 1)) == 0 && TILE_SIZE >= 4 && TILE_SIZE <= 16, "TILE_SIZE must be 4, 8 or 16");
    static_assert(PIXELS_PER_THREAD > 0, "CTA_SIZE must not exceed TILE_SIZE * TILE_SIZE");

    const std::uint32_t tile_id = blockIdx.x;
    const std::uint32_t tile_x  = tile_id % tile_width;
    const std::uint32_t tile_y  = tile_id / tile_width;

    const std::uint32_t tid      = threadIdx.x;
    const std::uint32_t thread_x = tid & TILE_MASK;
    const std::uint32_t thread_y = tid >> TILE_SHIFT;

    // x is shared by the thread's pixels; y steps by ROW_STRIDE rows. Pixel
    // centres sit at +0.5.
    const std::uint32_t out_x = tile_x * TILE_SIZE + thread_x;
    const float px            = static_cast<float>(out_x) + 0.5f;

    std::uint32_t out_y[PIXELS_PER_THREAD];
    float py[PIXELS_PER_THREAD];
    std::int32_t pix_id[PIXELS_PER_THREAD];
    float z_limit[PIXELS_PER_THREAD];
    TSR_UNROLL
    for(std::uint32_t p = 0; p < PIXELS_PER_THREAD; ++p)
    {
        out_y[p]  = tile_y * TILE_SIZE + thread_y + p * ROW_STRIDE;
        py[p]     = static_cast<float>(out_y[p]) + 0.5f;
        pix_id[p] = static_cast<std::int32_t>(out_y[p] * image_width + out_x);
    }

    // Out-of-image pixels cannot return early: __syncthreads_count below
    // needs every thread of the block.
    std::uint32_t done_mask = (out_x >= image_width) ? ALL_DONE : 0u;
    TSR_UNROLL
    for(std::uint32_t p = 0; p < PIXELS_PER_THREAD; ++p)
    {
        if(out_y[p] >= image_height)
        {
            done_mask |= (1u << p);
        }
        z_limit[p] = (done_mask & (1u << p)) ? 0.f : surface_depth[pix_id[p]];
    }

    const std::int32_t range_start = tile_offsets[tile_id];
    const std::int32_t range_end   = tile_offsets[tile_id + 1];
    const std::int32_t num_batches = (range_end - range_start + static_cast<std::int32_t>(BATCH_SIZE) - 1) / static_cast<std::int32_t>(BATCH_SIZE);

    TSR_DYNAMIC_SMEM(int, s);
    std::int32_t *id_batch  = reinterpret_cast<std::int32_t *>(s);                   // [BATCH_SIZE]
    float3 *xy_opacity_batch = reinterpret_cast<float3 *>(&id_batch[BATCH_SIZE]);     // [BATCH_SIZE]
    float3 *conic_batch      = reinterpret_cast<float3 *>(&xy_opacity_batch[BATCH_SIZE]); // [BATCH_SIZE]
    float *depth_batch       = reinterpret_cast<float *>(&conic_batch[BATCH_SIZE]);   // [BATCH_SIZE]

    float T[PIXELS_PER_THREAD];
    std::int32_t last_offset[PIXELS_PER_THREAD];
    float3 pix_out[PIXELS_PER_THREAD];
    TSR_UNROLL
    for(std::uint32_t p = 0; p < PIXELS_PER_THREAD; ++p)
    {
        T[p]           = 1.0f;
        last_offset[p] = 0;
        pix_out[p]     = make_float3(0.f, 0.f, 0.f);
    }

    TSR_NO_UNROLL
    for(std::int32_t b = 0; b < num_batches; ++b)
    {
        // each thread fetches one splat, front to back
        const std::int32_t batch_offset = static_cast<std::int32_t>(BATCH_SIZE) * b;
        const std::int32_t batch_start  = range_start + batch_offset;
        const std::int32_t idx          = batch_start + static_cast<std::int32_t>(tid);
        if(idx < range_end)
        {
            const std::int32_t g  = flatten_ids[idx];
            id_batch[tid]         = g;
            const float2 xy       = means2d[g];
            xy_opacity_batch[tid] = make_float3(xy.x, xy.y, opacities[g]);
            conic_batch[tid]      = conics[g];
            depth_batch[tid]      = depths[g];
        }

        // wait for the batch to be loaded
        if constexpr(CTA_SIZE <= 32)
        {
            __syncwarp();
        }
        else
        {
            __syncthreads();
        }

        const std::int32_t remaining   = range_end - batch_start;
        const std::uint32_t batch_size = static_cast<std::uint32_t>(remaining < static_cast<std::int32_t>(BATCH_SIZE) ? remaining : static_cast<std::int32_t>(BATCH_SIZE));
        for(std::uint32_t t = 0; (t < batch_size) && (done_mask != ALL_DONE); ++t)
        {
            const float3 conic   = conic_batch[t];
            const float3 xy_opac = xy_opacity_batch[t];
            const float depth    = depth_batch[t];
            const float dx       = xy_opac.x - px;

            TSR_UNROLL
            for(std::uint32_t p = 0; p < PIXELS_PER_THREAD; ++p)
            {
                if(done_mask & (1u << p))
                {
                    continue;
                }
                if(depth >= z_limit[p])
                {
                    // At or behind the surface; so is every later splat.
                    done_mask |= (1u << p);
                    continue;
                }
                const float dy          = xy_opac.y - py[p];
                const GaussianWeight gw = eval_gaussian_weight(conic, dx, dy, xy_opac.z);
                if(!gw.valid)
                {
                    continue;
                }
                const float next_T = T[p] * (1.0f - gw.alpha);
                if(next_T <= geom::kTransmittanceThreshold)
                {
                    // saturated: exclusive of this splat
                    done_mask |= (1u << p);
                    continue;
                }
                const float vis = gw.alpha * T[p];
                pix_out[p]     += colors[id_batch[t]] * vis;
                last_offset[p]  = batch_offset + static_cast<std::int32_t>(t);
                T[p]            = next_T;
            }
        }

        // resync before the next batch; stop once every pixel is done
        if(__syncthreads_count(done_mask == ALL_DONE) >= static_cast<int>(BATCH_SIZE))
        {
            break;
        }
    }

    if(out_x < image_width)
    {
        TSR_UNROLL
        for(std::uint32_t p = 0; p < PIXELS_PER_THREAD; ++p)
        {
            if(out_y[p] < image_height)
            {
                render_alphas[pix_id[p]] = 1.0f - T[p];
                render_colors[pix_id[p]] = pix_out[p] + T[p] * surface_color[pix_id[p]];
                last_ids[pix_id[p]]      = last_offset[p];
            }
        }
    }
}

template<std::uint32_t TILE_SIZE, std::uint32_t CTA_SIZE>
void launch_variant(
    const ProjectedSplats &splats,
    const TileBinning &binning,
    const SurfaceLayer &surface,
    const Camera &camera,
    SplatRasterOutput &out,
    cudaStream_t stream
)
{
    const std::size_t smem = CTA_SIZE * (sizeof(std::int32_t) + 2 * sizeof(float3) + sizeof(float));
    TSR_CUDA_CHECK(cudaFuncSetAttribute(
        rasterize_splats_kernel<TILE_SIZE, CTA_SIZE>, cudaFuncAttributeMaxDynamicSharedMemorySize, static_cast<int>(smem)
    ));
    launch(
        rasterize_splats_kernel<TILE_SIZE, CTA_SIZE>, LaunchConfig{dim3(binning.n_tiles()), dim3(CTA_SIZE), smem, stream},
        splats.means2d.data(), splats.conics.data(), splats.colors.data(), splats.opacities.data(), splats.depths.data(),
        camera.width, camera.height, binning.tiles_x, binning.tile_offsets.data(), binning.sorted_splat_ids.data(),
        surface.color.data(), surface.depth.data(), out.color.data(), out.alpha.data(), out.last_contributor.data()
    );
}
} // namespace

void rasterize_splats(
    const ProjectedSplats &splats,
    const TileBinning &binning,
    const SurfaceLayer &surface,
    const Camera &camera,
    const SplatRasterSettings &settings,
    SplatRasterOutput &out,
    cudaStream_t stream
)
{
    TSR_CHECK(surface.width == static_cast<int>(camera.width) && surface.height == static_cast<int>(camera.height),
              "surface layer does not match the camera resolution");
    const std::size_t n = static_cast<std::size_t>(camera.width) * camera.height;
    out.width           = static_cast<int>(camera.width);
    out.height          = static_cast<int>(camera.height);
    out.color.resize(n);
    out.alpha.resize(n);
    out.last_contributor.resize(n);
    if(binning.n_tiles() == 0)
    {
        return;
    }

    switch(binning.tile_size)
    {
    case 16:
        if(settings.pixels_per_thread == 4)
        {
            launch_variant<16, 64>(splats, binning, surface, camera, out, stream);
        }
        else
        {
            launch_variant<16, 256>(splats, binning, surface, camera, out, stream);
        }
        break;
    case 8: launch_variant<8, 64>(splats, binning, surface, camera, out, stream); break;
    case 4: launch_variant<4, 16>(splats, binning, surface, camera, out, stream); break;
    default: TSR_CHECK(false, "unsupported tile size " << binning.tile_size << "; supported values are {4, 8, 16}");
    }
}
} // namespace tsr
// Tessera - fine rasterization of binned mesh faces.
//
// Derived from PyTorch3D's RasterizeMeshesFineCudaKernel and the geometry
// helpers it uses (rasterize_meshes.cu, utils/geometry_utils.cuh,
// BSD-3-Clause, Copyright Meta Platforms, Inc. and affiliates). Reduced to one
// image; the clipped-face neighbour logic is dropped (Tessera does not clip).
#include <algorithm>
#include <vector>

#include "tsr/geom/mesh_ndc.cuh"
#include "tsr/math/vec.h"
#include "tsr/raster/mesh_raster.h"

namespace tsr
{
namespace
{
constexpr float kEpsilon = 1e-8f;

struct Pixel
{
    float z;
    std::int32_t idx; // face index
    float dist;       // signed squared distance of the pixel to the face
    float3 bary;
};

TSR_DI bool operator<(const Pixel &a, const Pixel &b) { return a.z < b.z || (a.z == b.z && a.idx < b.idx); }

TSR_DI float edge_function(const float2 &p, const float2 &v0, const float2 &v1)
{
    return (p.x - v0.x) * (v1.y - v0.y) - (p.y - v0.y) * (v1.x - v0.x);
}

TSR_DI float3 barycentric_coords(const float2 &p, const float2 &v0, const float2 &v1, const float2 &v2)
{
    const float area = edge_function(v2, v0, v1) + kEpsilon;
    const float w0   = edge_function(p, v1, v2) / area;
    const float w1   = edge_function(p, v2, v0) / area;
    const float w2   = edge_function(p, v0, v1) / area;
    return make_float3(w0, w1, w2);
}

TSR_DI float3 barycentric_perspective_correction(const float3 &bary, float z0, float z1, float z2)
{
    const float w0_top = bary.x * z1 * z2;
    const float w1_top = z0 * bary.y * z2;
    const float w2_top = z0 * z1 * bary.z;
    const float denom  = fmaxf(w0_top + w1_top + w2_top, kEpsilon);
    return make_float3(w0_top / denom, w1_top / denom, w2_top / denom);
}

TSR_DI float3 barycentric_clip(const float3 &bary)
{
    float3 w    = make_float3(fmaxf(bary.x, 0.f), fmaxf(bary.y, 0.f), fmaxf(bary.z, 0.f));
    const float sum = fmaxf(w.x + w.y + w.z, 1e-5f);
    w.x /= sum;
    w.y /= sum;
    w.z /= sum;
    return w;
}

// Squared distance from p to segment ab.
TSR_DI float point_line_distance(const float2 &p, const float2 &a, const float2 &b)
{
    const float2 ba = b - a;
    const float l2  = dot(ba, ba);
    if(l2 <= kEpsilon)
    {
        return dot(p - b, p - b);
    }
    const float t       = __saturatef(dot(ba, p - a) / l2);
    const float2 p_proj = a + t * ba;
    const float2 d      = p_proj - p;
    return dot(d, d);
}

TSR_DI float point_triangle_distance(const float2 &p, const float2 &v0, const float2 &v1, const float2 &v2)
{
    return fminf(fminf(point_line_distance(p, v0, v1), point_line_distance(p, v0, v2)), point_line_distance(p, v1, v2));
}

// Updates the per-pixel top-K queue (unsorted, with a cached maximum) with
// face `face_idx` if it covers pixel pxy.
TSR_DI void check_pixel_inside_face(
    const float3 *__restrict__ face_verts,
    int face_idx,
    int &q_size,
    float &q_max_z,
    int &q_max_idx,
    Pixel *q,
    float blur_radius,
    float2 pxy,
    int K,
    bool perspective_correct,
    bool clip_barycentric_coords,
    bool cull_backfaces
)
{
    const float3 v0 = face_verts[3 * face_idx + 0];
    const float3 v1 = face_verts[3 * face_idx + 1];
    const float3 v2 = face_verts[3 * face_idx + 2];

    const float2 v0xy = make_float2(v0.x, v0.y);
    const float2 v1xy = make_float2(v1.x, v1.y);
    const float2 v2xy = make_float2(v2.x, v2.y);

    // bounding box test, padded by the blur radius (in NDC units)
    const float r        = sqrtf(blur_radius);
    const float x_min    = fminf(v0.x, fminf(v1.x, v2.x)) - r;
    const float x_max    = fmaxf(v0.x, fmaxf(v1.x, v2.x)) + r;
    const float y_min    = fminf(v0.y, fminf(v1.y, v2.y)) - r;
    const float y_max    = fmaxf(v0.y, fmaxf(v1.y, v2.y)) + r;
    const float zmin     = fminf(v0.z, fminf(v1.z, v2.z));
    const float zmax     = fmaxf(v0.z, fmaxf(v1.z, v2.z));
    const bool outside   = pxy.x > x_max || pxy.x < x_min || pxy.y > y_max || pxy.y < y_min || zmin < kEpsilon;

    const float face_area      = edge_function(v0xy, v1xy, v2xy);
    const bool back_face       = face_area < 0.0f;
    const bool zero_face_area  = face_area <= kEpsilon && face_area >= -1.0f * kEpsilon;
    if(zmax < 0 || (cull_backfaces && back_face) || outside || zero_face_area)
    {
        return;
    }

    const float3 p_bary0     = barycentric_coords(pxy, v0xy, v1xy, v2xy);
    const float3 p_bary      = !perspective_correct ? p_bary0 : barycentric_perspective_correction(p_bary0, v0.z, v1.z, v2.z);
    const float3 p_bary_clip = !clip_barycentric_coords ? p_bary : barycentric_clip(p_bary);

    const float pz = p_bary_clip.x * v0.z + p_bary_clip.y * v1.z + p_bary_clip.z * v2.z;
    if(pz < 0)
    {
        return; // behind the image plane
    }

    // The inside test uses the unclipped barycentrics, otherwise every pixel
    // would count as inside.
    const float dist        = point_triangle_distance(pxy, v0xy, v1xy, v2xy);
    const bool inside       = p_bary.x > 0.0f && p_bary.y > 0.0f && p_bary.z > 0.0f;
    const float signed_dist = inside ? -dist : dist;
    if(!inside && dist >= blur_radius)
    {
        return;
    }

    if(q_size < K)
    {
        q[q_size] = {pz, face_idx, signed_dist, p_bary_clip};
        if(pz > q_max_z)
        {
            q_max_z   = pz;
            q_max_idx = q_size;
        }
        ++q_size;
    }
    else if(pz < q_max_z)
    {
        // Replace the current maximum, then find the new one.
        q[q_max_idx] = {pz, face_idx, signed_dist, p_bary_clip};
        q_max_z      = pz;
        for(int i = 0; i < K; ++i)
        {
            if(q[i].z > q_max_z)
            {
                q_max_z   = q[i].z;
                q_max_idx = i;
            }
        }
    }
}

template<typename T>
TSR_DI void bubble_sort(T *arr, int n)
{
    // Only used for tiny thread-local arrays, where divergence matters more
    // than asymptotic cost.
    for(int i = 0; i < n - 1; ++i)
    {
        for(int j = 0; j < n - i - 1; ++j)
        {
            if(arr[j + 1] < arr[j])
            {
                const T tmp = arr[j];
                arr[j]      = arr[j + 1];
                arr[j + 1]  = tmp;
            }
        }
    }
}

__global__ void rasterize_mesh_fine_kernel(
    const float3 *__restrict__ face_verts,
    const std::int32_t *__restrict__ faces_per_bin, // [BH][BW]
    const std::int32_t *__restrict__ bin_faces,     // [BH][BW][M]
    float blur_radius,
    int bin_size,
    bool perspective_correct,
    bool clip_barycentric_coords,
    bool cull_backfaces,
    int BH,
    int BW,
    int M,
    int H,
    int W,
    int K,
    std::int32_t *__restrict__ face_idxs,
    float *__restrict__ zbuf,
    float *__restrict__ pix_dists,
    float3 *__restrict__ bary
)
{
    // Can exceed H * W when the image is not divisible by bin_size.
    const int num_pixels  = BH * BW * bin_size * bin_size;
    const int num_threads = static_cast<int>(gridDim.x * blockDim.x);
    const int tid         = static_cast<int>(blockIdx.x * blockDim.x + threadIdx.x);

    for(int pid = tid; pid < num_pixels; pid += num_threads)
    {
        // Pixels within a bin move fastest so neighbouring threads share a
        // bin and read the same face list.
        int i        = pid;
        const int by = i / (BW * bin_size * bin_size);
        i           %= BW * bin_size * bin_size;
        const int bx = i / (bin_size * bin_size);
        i           %= bin_size * bin_size;

        // raster indices
        const int yi = i / bin_size + by * bin_size;
        const int xi = i % bin_size + bx * bin_size;
        if(yi >= H || xi >= W)
        {
            continue;
        }
        const float2 pxy = make_float2(geom::pix_to_non_square_ndc(xi, W, H), geom::pix_to_non_square_ndc(yi, H, W));

        Pixel q[kMaxFacesPerPixel];
        int q_size    = 0;
        float q_max_z = -1000.f;
        int q_max_idx = -1;

        const int bin      = by * BW + bx;
        const int n_in_bin = min(faces_per_bin[bin], M);
        for(int m = 0; m < n_in_bin; ++m)
        {
            const int f = bin_faces[bin * M + m];
            if(f < 0)
            {
                continue;
            }
            check_pixel_inside_face(
                face_verts, f, q_size, q_max_z, q_max_idx, q, blur_radius, pxy, K, perspective_correct,
                clip_barycentric_coords, cull_backfaces
            );
        }
        bubble_sort(q, q_size);

        // Raster index -> image index: +x NDC is left and +y NDC is up.
        const int yidx    = H - 1 - yi;
        const int xidx    = W - 1 - xi;
        const int pix_idx = (yidx * W + xidx) * K;
        for(int k = 0; k < q_size; ++k)
        {
            face_idxs[pix_idx + k] = q[k].idx;
            zbuf[pix_idx + k]      = q[k].z;
            pix_dists[pix_idx + k] = q[k].dist;
            bary[pix_idx + k]      = q[k].bary;
        }
    }
}
} // namespace

void rasterize_mesh_fine(
    const ViewFaces &faces,
    const MeshBins &bins,
    int width,
    int height,
    const MeshRasterSettings &settings,
    MeshFragments &out,
    cudaStream_t stream
)
{
    TSR_CHECK(settings.faces_per_pixel >= 1 && settings.faces_per_pixel <= kMaxFacesPerPixel,
              "faces_per_pixel must be in [1, " << kMaxFacesPerPixel << "]");
    const int K         = settings.faces_per_pixel;
    const std::size_t n = static_cast<std::size_t>(width) * height * K;
    out.width           = width;
    out.height          = height;
    out.faces_per_pixel = K;
    out.pix_to_face.resize(n);
    out.zbuf.resize(n);
    out.bary.resize(n);
    out.dists.resize(n);
    TSR_CUDA_CHECK(cudaMemsetAsync(out.pix_to_face.data(), 0xff, out.pix_to_face.bytes(), stream));
    // -1.0f everywhere: 0xbf800000
    std::vector<float> minus_one(n, -1.f);
    out.zbuf.upload(minus_one, stream);
    out.dists.upload(minus_one, stream);
    out.bary.zero(stream);
    if(faces.n_faces == 0)
    {
        return;
    }

    const int threads = 128;
    const int pixels  = bins.bins_x * bins.bins_y * bins.bin_size * bins.bin_size;
    const int blocks  = std::min(1024, div_round_up(pixels, threads));
    launch(
        rasterize_mesh_fine_kernel,
        LaunchConfig{dim3(blocks), dim3(threads), 0, stream},
        faces.ndc.data(), bins.faces_per_bin.data(), bins.bin_faces.data(), settings.blur_radius, bins.bin_size,
        settings.perspective_correct, settings.clip_barycentric_coords, settings.cull_backfaces, bins.bins_y,
        bins.bins_x, bins.max_faces_per_bin, height, width, K, out.pix_to_face.data(), out.zbuf.data(),
        out.dists.data(), out.bary.data()
    );
}
} // namespace tsr

// Tessera - camera model.
//
// Conventions (OpenCV style): camera space has +x right, +y down and +z
// forward; pixel (u, v) has its origin at the top-left corner of the image
// and the centre of pixel (i, j) is at (i + 0.5, j + 0.5).
#pragma once

#include <cstdint>

#include "tsr/device/backend.h"
#include "tsr/math/mat.h"
#include "tsr/math/vec.h"

namespace tsr
{
enum class CameraModel : std::uint32_t
{
    Pinhole      = 0,
    Orthographic = 1,
};

struct Camera
{
    math::mat3 R;   // world -> camera rotation (rows are the camera axes in world space)
    float3 t;       // world -> camera translation
    float fx, fy;   // focal lengths in pixels (pixels per world unit for orthographic)
    float cx, cy;   // principal point in pixels
    std::uint32_t width, height;
    float near_plane    = 0.01f;
    float far_plane     = 1e10f;
    CameraModel model   = CameraModel::Pinhole;

    TSR_HDI float3 world_to_camera(const float3 &p) const { return R * p + t; }

    TSR_HDI float3 position() const
    {
        // C = -R^T t
        const float3 c = math::transpose(R) * t;
        return make_float3(-c.x, -c.y, -c.z);
    }

    // Projects a camera-space point to continuous pixel coordinates.
    TSR_HDI float2 project(const float3 &pc) const
    {
        if(model == CameraModel::Orthographic)
        {
            return make_float2(fx * pc.x + cx, fy * pc.y + cy);
        }
        const float rz = 1.f / pc.z;
        return make_float2(fx * pc.x * rz + cx, fy * pc.y * rz + cy);
    }

    TSR_HDI std::uint32_t tiles_x(std::uint32_t tile) const { return (width + tile - 1) / tile; }
    TSR_HDI std::uint32_t tiles_y(std::uint32_t tile) const { return (height + tile - 1) / tile; }

    // Builds a pinhole camera at `eye` looking at `target`; `up` is the world
    // up direction and fov_y is the vertical field of view in degrees.
    static Camera look_at(float3 eye, float3 target, float3 up, float fov_y_degrees, std::uint32_t width, std::uint32_t height);
};

} // namespace tsr
// Tessera - small fixed-size matrices for device code.
//
// Column-major storage: Mat<C, R> has C columns of R rows and m[c][r] is the
// element in column c, row r (the GLSL/glm convention). Constructors take
// elements column by column. Products follow ordinary linear algebra:
// Mat<C, R> * Mat<K, C> -> Mat<K, R> and Mat<C, R> * vec<C> -> vec<R>.
#pragma once

#include "tsr/device/backend.h"
#include "tsr/math/vec.h"

namespace tsr::math
{
template<int N>
struct vec_of;
template<>
struct vec_of<2>
{
    using type = float2;
};
template<>
struct vec_of<3>
{
    using type = float3;
};
template<>
struct vec_of<4>
{
    using type = float4;
};
template<int N>
using vec_t = typename vec_of<N>::type;

TSR_HDI float comp(const float2 &v, int i) { return i == 0 ? v.x : v.y; }
TSR_HDI float comp(const float3 &v, int i) { return i == 0 ? v.x : (i == 1 ? v.y : v.z); }
TSR_HDI float comp(const float4 &v, int i) { return i == 0 ? v.x : (i == 1 ? v.y : (i == 2 ? v.z : v.w)); }

template<int N>
TSR_HDI vec_t<N> vec_from(const float *a)
{
    if constexpr(N == 2)
    {
        return make_float2(a[0], a[1]);
    }
    else if constexpr(N == 3)
    {
        return make_float3(a[0], a[1], a[2]);
    }
    else
    {
        return make_float4(a[0], a[1], a[2], a[3]);
    }
}

template<int C, int R>
struct Mat
{
    float m[C][R];

    TSR_HDI float *operator[](int c) { return m[c]; }
    TSR_HDI const float *operator[](int c) const { return m[c]; }

    TSR_HDI static Mat zero()
    {
        Mat out{};
        TSR_UNROLL
        for(int c = 0; c < C; ++c)
        {
            TSR_UNROLL
            for(int r = 0; r < R; ++r)
            {
                out.m[c][r] = 0.f;
            }
        }
        return out;
    }

    TSR_HDI static Mat identity()
    {
        static_assert(C == R, "identity requires a square matrix");
        Mat out = zero();
        TSR_UNROLL
        for(int i = 0; i < C; ++i)
        {
            out.m[i][i] = 1.f;
        }
        return out;
    }

    TSR_HDI static Mat diagonal(const vec_t<C> &d)
    {
        static_assert(C == R, "diagonal requires a square matrix");
        Mat out = zero();
        TSR_UNROLL
        for(int i = 0; i < C; ++i)
        {
            out.m[i][i] = comp(d, i);
        }
        return out;
    }

    TSR_HDI vec_t<R> col(int c) const { return vec_from<R>(m[c]); }

    TSR_HDI vec_t<C> row(int r) const
    {
        float tmp[C];
        TSR_UNROLL
        for(int c = 0; c < C; ++c)
        {
            tmp[c] = m[c][r];
        }
        return vec_from<C>(tmp);
    }
};

using mat2   = Mat<2, 2>;
using mat3   = Mat<3, 3>;
using mat4   = Mat<4, 4>;
using mat3x2 = Mat<3, 2>; // 3 columns, 2 rows: maps R^3 -> R^2
using mat2x3 = Mat<2, 3>;

// Column-major element-list constructors.
TSR_HDI mat2 make_mat2(float c0r0, float c0r1, float c1r0, float c1r1)
{
    return mat2{{{c0r0, c0r1}, {c1r0, c1r1}}};
}

TSR_HDI mat3 make_mat3(float c0r0, float c0r1, float c0r2, float c1r0, float c1r1, float c1r2, float c2r0, float c2r1, float c2r2)
{
    return mat3{{{c0r0, c0r1, c0r2}, {c1r0, c1r1, c1r2}, {c2r0, c2r1, c2r2}}};
}

TSR_HDI mat3x2 make_mat3x2(float c0r0, float c0r1, float c1r0, float c1r1, float c2r0, float c2r1)
{
    return mat3x2{{{c0r0, c0r1}, {c1r0, c1r1}, {c2r0, c2r1}}};
}

TSR_HDI mat3 make_mat3_cols(const float3 &c0, const float3 &c1, const float3 &c2)
{
    return make_mat3(c0.x, c0.y, c0.z, c1.x, c1.y, c1.z, c2.x, c2.y, c2.z);
}

template<int C, int R, int K>
TSR_HDI Mat<K, R> operator*(const Mat<C, R> &a, const Mat<K, C> &b)
{
    Mat<K, R> out;
    TSR_UNROLL
    for(int k = 0; k < K; ++k)
    {
        TSR_UNROLL
        for(int r = 0; r < R; ++r)
        {
            float acc = 0.f;
            TSR_UNROLL
            for(int c = 0; c < C; ++c)
            {
                acc += a.m[c][r] * b.m[k][c];
            }
            out.m[k][r] = acc;
        }
    }
    return out;
}

template<int C, int R>
TSR_HDI vec_t<R> operator*(const Mat<C, R> &a, const vec_t<C> &v)
{
    float tmp[R];
    TSR_UNROLL
    for(int r = 0; r < R; ++r)
    {
        float acc = 0.f;
        TSR_UNROLL
        for(int c = 0; c < C; ++c)
        {
            acc += a.m[c][r] * comp(v, c);
        }
        tmp[r] = acc;
    }
    return vec_from<R>(tmp);
}

// Explicit overloads so float2/3/4 arguments deduce without help.
TSR_HDI float2 operator*(const mat2 &a, const float2 &v) { return operator*<2, 2>(a, v); }
TSR_HDI float3 operator*(const mat3 &a, const float3 &v) { return operator*<3, 3>(a, v); }
TSR_HDI float4 operator*(const mat4 &a, const float4 &v) { return operator*<4, 4>(a, v); }
TSR_HDI float2 operator*(const mat3x2 &a, const float3 &v) { return operator*<3, 2>(a, v); }

template<int C, int R>
TSR_HDI Mat<C, R> operator+(const Mat<C, R> &a, const Mat<C, R> &b)
{
    Mat<C, R> out;
    TSR_UNROLL
    for(int c = 0; c < C; ++c)
    {
        TSR_UNROLL
        for(int r = 0; r < R; ++r)
        {
            out.m[c][r] = a.m[c][r] + b.m[c][r];
        }
    }
    return out;
}

template<int C, int R>
TSR_HDI Mat<C, R> operator*(const Mat<C, R> &a, float s)
{
    Mat<C, R> out;
    TSR_UNROLL
    for(int c = 0; c < C; ++c)
    {
        TSR_UNROLL
        for(int r = 0; r < R; ++r)
        {
            out.m[c][r] = a.m[c][r] * s;
        }
    }
    return out;
}

