// Tests for the execution model: barriers, shared memory, warp intrinsics,
// cooperative groups, atomics and launch validation. These run on whichever
// backend the library was built for.
#include <numeric>
#include <vector>

#include "doctest.h"
#include "tsr/device/backend.h"
#include "tsr/device/memory.h"

namespace
{
// Block-wide tree reduction through static shared memory.
__global__ void block_sum_kernel(const int *in, int *out, int n)
{
    __shared__ int s[256];
    const unsigned t = threadIdx.x;
    const unsigned i = blockIdx.x * blockDim.x + t;
    s[t]             = i < static_cast<unsigned>(n) ? in[i] : 0;
    __syncthreads();
    for(unsigned stride = blockDim.x / 2; stride > 0; stride >>= 1)
    {
        if(t < stride)
        {
            s[t] += s[t + stride];
        }
        __syncthreads();
    }
    if(t == 0)
    {
        out[blockIdx.x] = s[0];
    }
}

__global__ void warp_shuffle_kernel(const float *in, float *sum_out, float *bcast_out, float *up_out)
{
    const unsigned t = threadIdx.x;
    float v          = in[t];
    float sum        = v;
    for(int offset = 16; offset > 0; offset /= 2)
    {
        sum += __shfl_down_sync(0xffffffffu, sum, offset);
    }
    const float lane0 = __shfl_sync(0xffffffffu, v, 0);
    const float up    = __shfl_up_sync(0xffffffffu, v, 1);
    if((t & 31) == 0)
    {
        sum_out[t / 32] = sum;
    }
    bcast_out[t] = lane0;
    up_out[t]    = up;
}

__global__ void vote_kernel(const int *pred, unsigned *ballots, int *counts, int *alls)
{
    const unsigned t = threadIdx.x;
    const unsigned b = __ballot_sync(0xffffffffu, pred[t]);
    const int c      = __syncthreads_count(pred[t]);
    const int a      = __all_sync(0xffffffffu, pred[t]);
    if((t & 31) == 0)
    {
        ballots[t / 32] = b;
        alls[t / 32]    = a;
    }
    if(t == 0)
    {
        counts[0] = c;
    }
}

// Two 16-lane tiles of the same warp reduce independently.
__global__ void tile16_kernel(const int *in, int *out)
{
    auto block = cg::this_thread_block();
    auto tile  = cg::tiled_partition<16>(block);
    int v      = in[threadIdx.x];
    v          = cg::reduce(tile, v, cg::plus<int>());
    if(tile.thread_rank() == 0)
    {
        out[tile.meta_group_rank()] = v;
    }
}

__global__ void dynamic_smem_kernel(int *out)
{
    TSR_DYNAMIC_SMEM(int, s);
    s[threadIdx.x] = static_cast<int>(threadIdx.x) * 3;
    __syncthreads();
    out[blockIdx.x * blockDim.x + threadIdx.x] = s[blockDim.x - 1 - threadIdx.x];
}

__global__ void atomic_hist_kernel(const unsigned *in, unsigned n, unsigned *bins)
{
    const unsigned i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < n)
    {
        atomicAdd(&bins[in[i] % 8], 1u);
    }
}

__global__ void early_exit_kernel(int *out, int n)
{
    // Threads beyond n exit before the barrier; the rest must still proceed.
    const int t = static_cast<int>(threadIdx.x);
    if(t >= n)
    {
        return;
    }
    __shared__ int s[64];
    s[t] = t;
    __syncthreads();
    out[t] = s[n - 1 - t];
}

__global__ void axpy_kernel(unsigned n, float a, const float *x, float *y)
{
    const unsigned i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < n)
    {
        y[i] = a * x[i] + y[i];
    }
}

__global__ void noop_kernel(int *) {}
} // namespace

TEST_CASE("emu: block reduction through shared memory and barriers")
{
    const int n = 1000;
    std::vector<int> host(n);
    std::iota(host.begin(), host.end(), 1);
    tsr::DeviceBuffer<int> in, out(4);
    in.upload(host);
    tsr::launch(block_sum_kernel, {dim3(4), dim3(256)}, in.data(), out.data(), n);
    const auto partial = out.to_host();
    CHECK(std::accumulate(partial.begin(), partial.end(), 0) == n * (n + 1) / 2);
    CHECK(partial[0] == 256 * 257 / 2);
}

TEST_CASE("emu: warp shuffles")
{
    std::vector<float> host(64);
    std::iota(host.begin(), host.end(), 0.0f);
    tsr::DeviceBuffer<float> in, sums(2), bcast(64), up(64);
    in.upload(host);
    tsr::launch(warp_shuffle_kernel, {dim3(1), dim3(64)}, in.data(), sums.data(), bcast.data(), up.data());
    const auto s = sums.to_host();
    CHECK(s[0] == doctest::Approx(31 * 32 / 2));
    CHECK(s[1] == doctest::Approx((32 + 63) * 32 / 2));
    const auto b = bcast.to_host();
    CHECK(b[5] == 0.0f);
    CHECK(b[40] == 32.0f);
    const auto u = up.to_host();
    CHECK(u[0] == 0.0f);  // lane 0 keeps its own value
    CHECK(u[33] == 32.0f);
    CHECK(u[32] == 32.0f);
}

TEST_CASE("emu: ballot, all and __syncthreads_count")
{
    std::vector<int> pred(64, 0);
    for(int i = 0; i < 64; i += 3)
    {
        pred[i] = 1;
    }
    for(int i = 32; i < 64; ++i)
    {
        pred[i] = 1;
    }
    tsr::DeviceBuffer<int> p, counts(1), alls(2);
    tsr::DeviceBuffer<unsigned> ballots(2);
    p.upload(pred);
    tsr::launch(vote_kernel, {dim3(1), dim3(64)}, p.data(), ballots.data(), counts.data(), alls.data());
    unsigned expected0 = 0;
    for(int i = 0; i < 32; i += 3)
    {
        expected0 |= 1u << i;
    }
    const auto b = ballots.to_host();
    CHECK(b[0] == expected0);
    CHECK(b[1] == 0xffffffffu);
    CHECK(counts.to_host()[0] == std::accumulate(pred.begin(), pred.end(), 0));
    const auto a = alls.to_host();
    CHECK(a[0] == 0);
    CHECK(a[1] == 1);
}

TEST_CASE("emu: sub-warp tiles reduce independently")
{
    std::vector<int> host(64);
    std::iota(host.begin(), host.end(), 0);
    tsr::DeviceBuffer<int> in, out(4);
    in.upload(host);
    tsr::launch(tile16_kernel, {dim3(1), dim3(64)}, in.data(), out.data());
    const auto r = out.to_host();
    for(int t = 0; t < 4; ++t)
    {
        int expect = 0;
        for(int i = t * 16; i < t * 16 + 16; ++i)
        {
            expect += i;
        }
        CHECK(r[t] == expect);
    }
}

TEST_CASE("emu: dynamic shared memory")
{
    tsr::DeviceBuffer<int> out(3 * 32);
    tsr::launch(dynamic_smem_kernel, {dim3(3), dim3(32), 32 * sizeof(int)}, out.data());
    const auto r = out.to_host();
    CHECK(r[0] == 31 * 3);
    CHECK(r[32 + 31] == 0);
}

TEST_CASE("emu: global atomics across concurrently running blocks")
{
    const unsigned n = 5000;
    std::vector<unsigned> host(n);
    std::iota(host.begin(), host.end(), 0u);
    tsr::DeviceBuffer<unsigned> in, bins(8);
    in.upload(host);
    bins.zero();
    tsr::launch(atomic_hist_kernel, {dim3(tsr::div_round_up(n, 128u)), dim3(128)}, in.data(), n, bins.data());
    const auto b = bins.to_host();
    CHECK(std::accumulate(b.begin(), b.end(), 0u) == n);
    CHECK(b[0] == 625u);
}

TEST_CASE("emu: threads that exit early do not block the barrier")
{
    tsr::DeviceBuffer<int> out(64);
    out.zero();
    tsr::launch(early_exit_kernel, {dim3(1), dim3(64)}, out.data(), 40);
    const auto r = out.to_host();
    CHECK(r[0] == 39);
    CHECK(r[39] == 0);
    CHECK(r[40] == 0);
}

TEST_CASE("emu: linear launches")
{
    const unsigned n = 1000;
    std::vector<float> x(n, 2.0f), y(n, 1.0f);
    tsr::DeviceBuffer<float> dx, dy;
    dx.upload(x);
    dy.upload(y);
    tsr::launch_linear(axpy_kernel, n, nullptr, n, 3.0f, dx.data(), dy.data());
    const auto r = dy.to_host();
    CHECK(r[0] == 7.0f);
    CHECK(r[n - 1] == 7.0f);
}

TEST_CASE("emu: invalid launch configurations are reported")
{
    CHECK_THROWS_AS(tsr::launch(noop_kernel, {dim3(1), dim3(2048)}, nullptr), tsr::DeviceError);
    CHECK_THROWS_AS(tsr::launch(noop_kernel, {dim3(1), dim3(32), 200 * 1024}, nullptr), tsr::DeviceError);
    CHECK_NOTHROW(tsr::launch(noop_kernel, {dim3(1), dim3(32)}, nullptr));
}
// Tessera - the hybrid splat + mesh renderer.
#include "tsr/prims/prims.h"
#include "tsr/render/renderer.h"

namespace tsr
{
namespace
{
constexpr std::size_t kInitialArenaBytes = std::size_t{4} << 20;

__global__ void visible_flags_kernel(std::uint32_t n, const int2 *__restrict__ radii, std::uint32_t *__restrict__ flags)
{
    const std::uint32_t i = blockIdx.x * blockDim.x + threadIdx.x;
    if(i < n)
    {
        const int2 r = radii[i];
        flags[i]     = (r.x > 0 && r.y > 0) ? 1u : 0u;
    }
}
} // namespace

Renderer::Renderer(const RenderSettings &settings) : settings_(settings), arena_(kInitialArenaBytes)
{
    TSR_CUDA_CHECK(cudaStreamCreateWithFlags(&stream_, cudaStreamNonBlocking));
}

Renderer::~Renderer()
{
    if(stream_ != nullptr)
    {
        cudaStreamSynchronize(stream_);
        cudaStreamDestroy(stream_);
    }
}

void Renderer::set_scene(const Scene &scene)
{
    gaussians_.upload(scene.gaussians, stream_);
    mesh_.upload(scene.meshes, stream_);
    if(mesh_.n_faces > 0)
    {
        material_.initialize(scene.material, stream_);
    }
    background_ = scene.background;
    TSR_CUDA_CHECK(cudaStreamSynchronize(stream_));
    has_scene_ = true;
}

void Renderer::render_surface(const Camera &camera)
{
    const int W    = static_cast<int>(camera.width);
    const int H    = static_cast<int>(camera.height);
    mesh_overflow_ = false;
    if(mesh_.n_faces == 0)
    {
        clear_surface(W, H, background_, surface_, stream_);
        fragments_ = MeshFragments{};
        return;
    }
    transform_faces(mesh_, camera, faces_, stream_);
    bin_mesh_faces(faces_, W, H, settings_.mesh_binning, mesh_bins_, arena_, stream_);
    mesh_overflow_ = mesh_bins_.overflowed;
    rasterize_mesh_fine(faces_, mesh_bins_, W, H, settings_.mesh_raster, fragments_, stream_);
    shade_surface(material_, fragments_, faces_, camera, background_, surface_, arena_, stream_);
}

std::uint32_t Renderer::count_visible_splats()
{
    const std::uint32_t n = splats_.count;
    if(n == 0)
    {
        return 0;
    }
    std::uint32_t *flags = arena_.allocate<std::uint32_t>(n);
    std::uint32_t *total = arena_.allocate<std::uint32_t>(1);
    launch_linear(visible_flags_kernel, n, stream_, n, splats_.radii.data(), flags);
    prims::reduce(flags, n, total, prims::ReduceOp::Sum, arena_, stream_);
    std::uint32_t host_total = 0;
    TSR_CUDA_CHECK(cudaMemcpyAsync(&host_total, total, sizeof(host_total), cudaMemcpyDeviceToHost, stream_));
    TSR_CUDA_CHECK(cudaStreamSynchronize(stream_));
    return host_total;
}

Frame Renderer::render(const Camera &camera)
{
    TSR_CHECK(has_scene_, "Renderer::render called before set_scene");
    TSR_CHECK(camera.width > 0 && camera.height > 0, "camera has an empty image");
    arena_.reset();

    // opaque surface layer
    render_surface(camera);

    // splats
    project_gaussians(gaussians_, camera, settings_.projection, splats_, stream_);
    compute_splat_colors(gaussians_, camera, splats_, stream_);
    bin_splats(splats_, camera, settings_.binning, binning_, arena_, stream_);

    // composite
    rasterize_splats(splats_, binning_, surface_, camera, settings_.splat_raster, composite_, stream_);

    // post
    const std::size_t n_pixels = static_cast<std::size_t>(camera.width) * camera.height;
    ldr_.resize(n_pixels);
    Frame frame;
    frame.width  = static_cast<int>(camera.width);
    frame.height = static_cast<int>(camera.height);
    tonemap(composite_.color.data(), frame.width, frame.height, settings_.tonemap, ldr_.data(), &frame.stats.tonemap, arena_, stream_);

    frame.stats.visible_splats       = count_visible_splats();
    frame.stats.intersections        = binning_.n_isects;
    frame.stats.surface_pixels       = surface_.covered_pixels;
    frame.stats.mesh_bins_overflowed = mesh_overflow_;
    frame.linear                     = composite_.color.to_host(stream_);
    frame.alpha                      = composite_.alpha.to_host(stream_);
    frame.rgba8                      = ldr_.to_host(stream_);
    frame.stats.scratch_bytes        = arena_.high_water();
    return frame;
}
} // namespace tsr
// Tessera - parallel rendering of many views.
#include "tsr/sched/frame_scheduler.h"

namespace tsr
{
FrameScheduler::FrameScheduler(const Scene &scene, const RenderSettings &settings, std::size_t workers)
    : scene_(scene), settings_(settings), pool_(workers), renderers_(pool_.get_thread_count()), init_flags_(pool_.get_thread_count())
{
}

FrameScheduler::~FrameScheduler()
{
    pool_.wait();
}

Renderer &FrameScheduler::renderer_for_this_thread()
{
    const auto idx = sched::this_thread::get_index();
    TSR_CHECK(idx.has_value() && sched::this_thread::get_pool() == &pool_, "renderer requested outside the scheduler's pool");
    std::call_once(init_flags_[*idx],
                   [&]
                   {
                       auto r = std::make_unique<Renderer>(settings_);
                       r->set_scene(scene_);
                       renderers_[*idx] = std::move(r);
                   });
    return *renderers_[*idx];
}

void FrameScheduler::render_each(const std::vector<Camera> &cameras, const std::function<void(std::size_t, Frame &&)> &on_frame)
{
    sched::multi_future<void> done;
    done.reserve(cameras.size());
    for(std::size_t i = 0; i < cameras.size(); ++i)
    {
        done.push_back(pool_.submit_task(
            [this, &cameras, &on_frame, i]
            {
                Frame f = renderer_for_this_thread().render(cameras[i]);
                on_frame(i, std::move(f));
            }
        ));
    }
    // Wait for all views before propagating the first error, so no task
    // outlives the references it captured.
    done.wait();
    done.get();
}

std::vector<Frame> FrameScheduler::render_all(const std::vector<Camera> &cameras)
{
    std::vector<Frame> frames(cameras.size());
    std::mutex m;
    render_each(cameras,
                [&](std::size_t i, Frame &&f)
                {
                    const std::scoped_lock lock(m);
                    frames[i] = std::move(f);
                });
    return frames;
}
} // namespace tsr
// Tessera - projection of 3D Gaussians into screen-space splats.
//
// The projection kernel follows gsplat's fused EWA projection
// (projection_ewa_3dgs_fused_fwd_kernel, Apache-2.0), specialised to one
// camera and to quaternion/scale parameterised covariances.
#include "tsr/geom/gaussian_math.cuh"
#include "tsr/geom/projection.h"

namespace tsr
{
namespace
{
__global__ void project_gaussians_kernel(
    std::uint32_t n,
    const float3 *__restrict__ means,
    const float4 *__restrict__ quats,
    const float3 *__restrict__ scales,
    const float *__restrict__ opacities,
    const Camera camera,
    const float eps2d,
    const float radius_clip,
    const bool antialiased,
    int2 *__restrict__ radii,
    float2 *__restrict__ means2d,
    float *__restrict__ depths,
    float3 *__restrict__ conics,
    float *__restrict__ out_opacities
)
{
    const std::uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx >= n)
    {
        return;
    }

    // transform Gaussian centre to camera space
    const float3 mean_c = camera.world_to_camera(means[idx]);
    if(mean_c.z < camera.near_plane || mean_c.z > camera.far_plane)
    {
        radii[idx] = make_int2(0, 0);
        return;
    }

    // transform covariance to camera space
    const math::mat3 covar   = geom::quat_scale_to_covar(quats[idx], scales[idx]);
    const math::mat3 covar_c = geom::covar_world_to_camera(camera.R, covar);

    math::mat2 covar2d = math::mat2::zero();
    float2 mean2d      = make_float2(0.f, 0.f);
    switch(camera.model)
    {
    case CameraModel::Pinhole:
        geom::persp_proj(mean_c, covar_c, camera.fx, camera.fy, camera.cx, camera.cy, camera.width, camera.height, covar2d, mean2d);
        break;
    case CameraModel::Orthographic:
        geom::ortho_proj(mean_c, covar_c, camera.fx, camera.fy, camera.cx, camera.cy, covar2d, mean2d);
        break;
    }

    float compensation;
    const float det = geom::add_blur(eps2d, covar2d, compensation);
    if(det <= 0.f)
    {
        radii[idx] = make_int2(0, 0);
        return;
    }
    const math::mat2 covar2d_inv = math::inverse(covar2d);

    float opacity = opacities[idx];
    if(antialiased)
    {
        opacity *= compensation;
    }
    if(opacity < geom::kAlphaThreshold)
    {
        radii[idx] = make_int2(0, 0);
        return;
    }
    // Opacity-aware extent: alpha = opacity * exp(-q / 2) drops below the
    // threshold at q = 2 ln(opacity / threshold) (arXiv:2402.00525, B.2).
    const float extent = fminf(geom::kGaussianExtent, sqrtf(2.0f * __logf(opacity / geom::kAlphaThreshold)));

    // tight axis-aligned bounding box (non differentiable)
    const float radius_x = ceilf(extent * sqrtf(covar2d[0][0]));
    const float radius_y = ceilf(extent * sqrtf(covar2d[1][1]));
    if(radius_x <= radius_clip && radius_y <= radius_clip)
    {
        radii[idx] = make_int2(0, 0);
        return;
    }

    // cull splats entirely outside the image
    if(mean2d.x + radius_x <= 0 || mean2d.x - radius_x >= camera.width || mean2d.y + radius_y <= 0
       || mean2d.y - radius_y >= camera.height)
    {
        radii[idx] = make_int2(0, 0);
        return;
    }

    radii[idx]         = make_int2(static_cast<int>(radius_x), static_cast<int>(radius_y));
    means2d[idx]       = mean2d;
    depths[idx]        = mean_c.z;
    conics[idx]        = math::pack_sym(covar2d_inv);
    out_opacities[idx] = opacity;
}

__global__ void splat_colors_kernel(
    std::uint32_t n,
    std::uint32_t sh_degree,
    const float3 *__restrict__ means,
    const float *__restrict__ sh,
    const int2 *__restrict__ radii,
    const float3 camera_position,
    float3 *__restrict__ colors
)
{
    const std::uint32_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if(idx >= n)
    {
        return;
    }
    const int2 r = radii[idx];
    if(r.x <= 0 && r.y <= 0)
    {
        return;
    }
    const std::uint32_t K = geom::sh_coeff_count(sh_degree);
    const float *coeffs   = sh + static_cast<std::size_t>(idx) * K * 3;
    const float3 dir      = means[idx] - camera_position;
    // 3DGS convention: radiance = SH(dir) + 0.5, clamped at zero.
    colors[idx] = make_float3(
        fmaxf(geom::sh_to_color(sh_degree, 0, dir, coeffs) + 0.5f, 0.f),
        fmaxf(geom::sh_to_color(sh_degree, 1, dir, coeffs) + 0.5f, 0.f),
        fmaxf(geom::sh_to_color(sh_degree, 2, dir, coeffs) + 0.5f, 0.f)
    );
}
} // namespace

void DeviceGaussians::upload(const GaussianCloud &cloud, cudaStream_t stream)
{
    cloud.validate();
    count     = static_cast<std::uint32_t>(cloud.size());
    sh_degree = cloud.sh_degree;
    means.upload(cloud.means, stream);
    quats.upload(cloud.quats, stream);
    scales.upload(cloud.scales, stream);
    opacities.upload(cloud.opacities, stream);
    sh.upload(cloud.sh, stream);
}

void ProjectedSplats::resize(std::uint32_t n)
{
    count = n;
    radii.resize(n);
    means2d.resize(n);
    depths.resize(n);
    conics.resize(n);
    opacities.resize(n);
    colors.resize(n);
}

void project_gaussians(
    const DeviceGaussians &gaussians,
    const Camera &camera,
    const ProjectionSettings &settings,
    ProjectedSplats &out,
    cudaStream_t stream
)
{
    out.resize(gaussians.count);
    launch_linear(
        project_gaussians_kernel,
        gaussians.count,
        stream,
        gaussians.count,
        gaussians.means.data(),
        gaussians.quats.data(),
        gaussians.scales.data(),
        gaussians.opacities.data(),
        camera,
        settings.eps2d,
        settings.radius_clip,
        settings.antialiased,
        out.radii.data(),
        out.means2d.data(),
        out.depths.data(),
        out.conics.data(),
        out.opacities.data()
    );
}

void compute_splat_colors(const DeviceGaussians &gaussians, const Camera &camera, ProjectedSplats &splats, cudaStream_t stream)
{
    TSR_CHECK(splats.count == gaussians.count, "splats were projected from a different Gaussian set");
    TSR_CHECK(gaussians.sh_degree <= 3, "SH degree " << gaussians.sh_degree << " is not supported (max 3)");
    launch_linear(
        splat_colors_kernel,
        gaussians.count,
        stream,
        gaussians.count,
        gaussians.sh_degree,
        gaussians.means.data(),
        gaussians.sh.data(),
        splats.radii.data(),
        camera.position(),
        splats.colors.data()
    );
}
} // namespace tsr
// Tessera - triangle meshes on the device and their view transform.
#include "tsr/geom/mesh.h"
#include "tsr/geom/mesh_ndc.cuh"

namespace tsr
{
namespace
{
__global__ void transform_faces_kernel(
    std::uint32_t n_faces,
    const float3 *__restrict__ vertices,
    const int3 *__restrict__ faces,
    const Camera camera,
    float3 *__restrict__ face_ndc,
    float3 *__restrict__ face_world,
    float3 *__restrict__ face_normals
)
{
    const std::uint32_t f = blockIdx.x * blockDim.x + threadIdx.x;
    if(f >= n_faces)
    {
        return;
    }
    const int3 tri = faces[f];
    const int idx[3] = {tri.x, tri.y, tri.z};
    const int W      = static_cast<int>(camera.width);
    const int H      = static_cast<int>(camera.height);
    float3 world[3];
    TSR_UNROLL
    for(int k = 0; k < 3; ++k)
    {
        world[k]            = vertices[idx[k]];
        const float3 pc     = camera.world_to_camera(world[k]);
        const float2 pix    = camera.project(pc);
        face_ndc[3 * f + k] = make_float3(geom::pixel_x_to_ndc(pix.x, W, H), geom::pixel_y_to_ndc(pix.y, H, W), pc.z);
        face_world[3 * f + k] = world[k];
    }
    const float3 n   = cross(world[1] - world[0], world[2] - world[0]);
    const float len2 = dot(n, n);
    face_normals[f]  = len2 > 0.f ? n * rsqrtf(len2) : make_float3(0.f, 0.f, 0.f);
}
} // namespace

void DeviceMesh::upload(const std::vector<TriangleMesh> &meshes, cudaStream_t stream)
{
    std::vector<float3> all_vertices;
    std::vector<int3> all_faces;
    for(const TriangleMesh &m : meshes)
    {
        const int base = static_cast<int>(all_vertices.size());
        for(const int3 &f : m.faces)
        {
            TSR_CHECK(f.x >= 0 && f.y >= 0 && f.z >= 0 && static_cast<std::size_t>(f.x) < m.vertices.size()
                          && static_cast<std::size_t>(f.y) < m.vertices.size() && static_cast<std::size_t>(f.z) < m.vertices.size(),
                      "mesh '" << m.name << "' has a face referencing a missing vertex");
            all_faces.push_back(make_int3(f.x + base, f.y + base, f.z + base));
        }
        all_vertices.insert(all_vertices.end(), m.vertices.begin(), m.vertices.end());
    }
    n_vertices = static_cast<std::uint32_t>(all_vertices.size());
    n_faces    = static_cast<std::uint32_t>(all_faces.size());
    vertices.upload(all_vertices, stream);
    faces.upload(all_faces, stream);
}

void transform_faces(const DeviceMesh &mesh, const Camera &camera, ViewFaces &out, cudaStream_t stream)
{
    out.n_faces = mesh.n_faces;
    out.ndc.resize(static_cast<std::size_t>(mesh.n_faces) * 3);
    out.world.resize(static_cast<std::size_t>(mesh.n_faces) * 3);
    out.normals.resize(mesh.n_faces);
    launch_linear(
        transform_faces_kernel, mesh.n_faces, stream, mesh.n_faces, mesh.vertices.data(), mesh.faces.data(), camera,
        out.ndc.data(), out.world.data(), out.normals.data()
    );
}
} // namespace tsr

// Tessera - emulated device backend
// Built-in vector types with the same names, layout and alignment as CUDA's
// <vector_types.h>, so device code compiles unchanged on the host backend.
#pragma once

#include <cstddef>
#include <cstdint>

#define TSR_EMU_VEC2(T, NAME, ALIGN)       \
    struct alignas(ALIGN) NAME             \
    {                                      \
        T x, y;                            \
    };                                     \
    inline constexpr NAME make_##NAME(T x, T y) { return NAME{x, y}; }

#define TSR_EMU_VEC3(T, NAME)              \
    struct NAME                            \
    {                                      \
        T x, y, z;                         \
    };                                     \
    inline constexpr NAME make_##NAME(T x, T y, T z) { return NAME{x, y, z}; }

#define TSR_EMU_VEC4(T, NAME, ALIGN)       \
    struct alignas(ALIGN) NAME             \
    {                                      \
        T x, y, z, w;                      \
    };                                     \
    inline constexpr NAME make_##NAME(T x, T y, T z, T w) { return NAME{x, y, z, w}; }

