namespace tsr { namespace { constexpr float kLumEpsilon=1e-4f;
#pragma omp declare target
TSR_HDI float luminance(const float3&c){return .2126f*c.x+.7152f*c.y+.0722f*c.z;}TSR_HDI float srgb_encode(float x){x=fminf(fmaxf(x,0.f),1.f);return x<=.0031308f?12.92f*x:1.055f*powf(x,1.f/2.4f)-.055f;}TSR_HDI unsigned char unorm(float x){return (unsigned char)(fminf(fmaxf(x,0.f),1.f)*255.f+.5f);}void map_one(std::uint32_t i,const float3*hdr,bool enabled,float exposure,float iw,uchar4*out){float3 c=hdr[i];if(enabled){c*=exposure;float L=luminance(c),Ld=L*(1+L*iw)/(1+L);c=L>0?c*(Ld/L):make_float3(0.f);}out[i]=make_uchar4(unorm(srgb_encode(c.x)),unorm(srgb_encode(c.y)),unorm(srgb_encode(c.z)),255);}
#pragma omp end declare target
}
