void tonemap(const float3*hdr,int w,int h,const TonemapSettings&set,uchar4*out,TonemapStats*stats,Arena&arena,Stream stream){auto n=(std::uint32_t)(w*h);if(!n)return;TonemapStats local;auto&s=stats?*stats:local;s=TonemapStats{};if(!set.enabled){
#pragma omp target teams distribute parallel for is_device_ptr(hdr,out)
 for(std::uint32_t i=0;i<n;++i)map_one(i,hdr,false,1,1,out);return;}TSR_CHECK(set.white_percentile>0&&set.white_percentile<=1,"white percentile must be in (0, 1]");auto*logs=arena.allocate<float>(n);
#pragma omp target teams distribute parallel for is_device_ptr(hdr,logs)
 for(std::uint32_t i=0;i<n;++i)logs[i]=logf(kLumEpsilon+luminance(hdr[i]));auto*sum=arena.allocate<float>(1);prims::reduce(logs,n,sum,prims::ReduceOp::Sum,arena,stream);float hs;detail::copy_from_device(&hs,sum,sizeof(hs));s.log_average_luminance=std::exp(hs/n);s.exposure=set.key/s.log_average_luminance;auto*bins=arena.allocate<std::uint32_t>(n);float exposure=s.exposure;
#pragma omp target teams distribute parallel for is_device_ptr(hdr,bins)
 for(std::uint32_t i=0;i<n;++i){float L=luminance(hdr[i])*exposure;if(L<=0)bins[i]=0;else{float t=(log2f(L)-kHistogramMinLog2)/(kHistogramMaxLog2-kHistogramMinLog2);bins[i]=(std::uint32_t)fminf(fmaxf(t*256,0),255);}}
 auto*hist=arena.allocate<std::uint32_t>(256);prims::histogram256(bins,n,hist,arena,stream);detail::copy_from_device(s.histogram.data(),hist,256*sizeof(std::uint32_t));auto*white=arena.allocate<std::uint32_t>(1);double target=set.white_percentile*(double)n;
#pragma omp target teams num_teams(1) thread_limit(1) is_device_ptr(hist,white)
 {std::uint32_t run=0,b=255;for(std::uint32_t i=0;i<256;++i){run+=hist[i];if((double)run>=target){b=i;break;}}*white=b;}
 std::uint32_t wb;detail::copy_from_device(&wb,white,sizeof(wb));float lw=kHistogramMinLog2+(wb+1)*(kHistogramMaxLog2-kHistogramMinLog2)/256.f;s.white_point=std::fmax(std::exp2(lw),1e-3f);float iw=1/(s.white_point*s.white_point);
#pragma omp target teams distribute parallel for is_device_ptr(hdr,out)
 for(std::uint32_t i=0;i<n;++i)map_one(i,hdr,true,exposure,iw,out);
}
}
